code:
@PostMapping("/importConfig")
    @Transactional
    public Result importConfig(MultipartFile file, String groupid) throws Exception {
        if (file == null || file.isEmpty()) {
            return Result.error("请选择要导入的文件");
        }

        try (InputStream is = file.getInputStream(); Workbook workbook = new XSSFWorkbook(is)) {
            int totalCount = 0;
            List<String> errors = new ArrayList<>();

            // 处理结转损益页签
            Sheet lossSheet = workbook.getSheet("结转损益");
            if (lossSheet != null && lossSheet.getLastRowNum() > 0) {
                // 解析表头，获取列索引
                Row headerRow = lossSheet.getRow(0);
                if (headerRow != null) {
                    Map<String, Integer> columnMap = new HashMap<>();
                    for (int j = 0; j < headerRow.getLastCellNum(); j++) {
                        String header = getCellStringValue(headerRow.getCell(j));
                        if (header != null) {
                            // 去掉括号内的说明文字进行匹配
                            String key = header.contains("(") ? header.substring(0, header.indexOf("(")) : header;
                            columnMap.put(key, j);
                        }
                    }

                    for (int i = 1; i <= lossSheet.getLastRowNum(); i++) {
                        Row row = lossSheet.getRow(i);
                        if (row == null) continue;

                        try {
                            Integer templateNameIdx = columnMap.get("模板名称");
                            String templateName = templateNameIdx != null ? getCellStringValue(row.getCell(templateNameIdx)) : null;
                            if (templateName == null || templateName.isEmpty()) continue;

                            // 查找或创建模板
                            FinClosingTemplate template = findOrCreateTemplate(templateName, "loss", groupid,null);

                            // 创建结转损益配置
                            FinClosingTemplateProfitLoss profitLoss = new FinClosingTemplateProfitLoss();
                            profitLoss.setTemplateId(template.getId());
                            profitLoss.setGroupid(groupid);
                            // 结转周期：按月结转->0，按年结转->1
                            String transferCycle = columnMap.containsKey("结转周期") ? getCellStringValue(row.getCell(columnMap.get("结转周期"))) : null;
                            profitLoss.setTransferCycle("按月结转".equals(transferCycle) ? "0" : "按年结转".equals(transferCycle) ? "1" : transferCycle);
                            // 结转方式：追加结转->0，重新结转->1
                            String transferMethod = columnMap.containsKey("结转方式") ? getCellStringValue(row.getCell(columnMap.get("结转方式"))) : null;
                            profitLoss.setTransferMethod("追加结转".equals(transferMethod) ? "0" : "重新结转".equals(transferMethod) ? "1" : transferMethod);
                            profitLoss.setSummary(columnMap.containsKey("凭证摘要") ? getCellStringValue(row.getCell(columnMap.get("凭证摘要"))) : null);
                            // 方向处理：按科目方向反向结转->0，按金额正数结转->1
                            String directionHandling = columnMap.containsKey("方向处理") ? getCellStringValue(row.getCell(columnMap.get("方向处理"))) : null;
                            profitLoss.setDirectionHandling("按科目方向反向结转".equals(directionHandling) ? 0 : "按金额正数结转".equals(directionHandling) ? 1 : null);
                            profitLoss.setProfitLossSubjectCode(columnMap.containsKey("损益科目编码") ? getCellStringValue(row.getCell(columnMap.get("损益科目编码"))) : null);
                            profitLoss.setCurrentYearProfitSubjectCode(columnMap.containsKey("本年利润科目编码") ? getCellStringValue(row.getCell(columnMap.get("本年利润科目编码"))) : null);
                            profitLoss.setPriorYearAdjustmentSubjectCode(columnMap.containsKey("以前年度损益调整科目编码") ? getCellStringValue(row.getCell(columnMap.get("以前年度损益调整科目编码"))) : null);
                            profitLoss.setPriorYearAdjustTransferSubjectCode(columnMap.containsKey("调整结转科目编码") ? getCellStringValue(row.getCell(columnMap.get("调整结转科目编码"))) : null);
                            profitLoss.setCreateBy(UserInfoContext.get().getUserName());
                            profitLoss.setCreatedTime(new Date());
                            profitLoss.setModifyBy(UserInfoContext.get().getUserName());
                            profitLoss.setUpdatedTime(new Date());

                            // 检查是否已存在该模板的配置
                            FinClosingTemplateProfitLoss existQuery = new FinClosingTemplateProfitLoss();
                            existQuery.setTemplateId(template.getId());
                            List<FinClosingTemplateProfitLoss> existList = finClosingTemplateProfitLossService.selectFinClosingTemplateProfitLossList(existQuery);
                            if (existList != null && !existList.isEmpty()) {
                                // 更新现有记录
                                profitLoss.setId(existList.get(0).getId());
                                finClosingTemplateProfitLossService.updateFinClosingTemplateProfitLoss(profitLoss);
                            } else {
                                // 插入新记录
                                finClosingTemplateProfitLossService.insertFinClosingTemplateProfitLoss(profitLoss);
                            }
                            totalCount++;
                        } catch (Exception e) {
                            errors.add("结转损益第" + (i + 1) + "行: " + e.getMessage());
                        }
                    }
                }
            }

            // 处理亚马逊报表页签
            Sheet amazonSheet = workbook.getSheet("亚马逊报表");
            System.out.println("亚马逊报表页签: " + (amazonSheet != null ? "存在" : "不存在"));
            if (amazonSheet != null) {
                System.out.println("亚马逊报表行数: " + amazonSheet.getLastRowNum());
            }
            if (amazonSheet != null && amazonSheet.getLastRowNum() > 0) {
                // 解析表头，获取列索引
                Row amazonHeaderRow = amazonSheet.getRow(0);
                if (amazonHeaderRow != null) {
                    Map<String, Integer> amazonColumnMap = new HashMap<>();
                    for (int j = 0; j < amazonHeaderRow.getLastCellNum(); j++) {
                        String header = getCellStringValue(amazonHeaderRow.getCell(j));
                        if (header != null) {
                            String key = header.contains("(") ? header.substring(0, header.indexOf("(")) : header;
                            amazonColumnMap.put(key, j);
                            System.out.println("亚马逊报表列: " + key + " -> " + j);
                        }
                    }

                    Set<String> processedAmazonTemplates = new HashSet<>();

                    for (int i = 1; i <= amazonSheet.getLastRowNum(); i++) {
                        Row row = amazonSheet.getRow(i);
                        if (row == null) continue;

                        try {
                            Integer templateNameIdx = amazonColumnMap.get("模板名称");
                            String templateName = templateNameIdx != null ? getCellStringValue(row.getCell(templateNameIdx)) : null;
                            System.out.println("亚马逊报表第" + i + "行模板名称: " + templateName);
                            if (templateName == null || templateName.isEmpty()) continue;
                            String country = amazonColumnMap.containsKey("国家") ? getCellStringValue(row.getCell(amazonColumnMap.get("国家"))) : null;
                            FinClosingTemplate template = findOrCreateTemplate(templateName, "amzpayment", groupid, country);
                            System.out.println("找到模板: " + template.getName() + ", ID: " + template.getId());
                            // 添加国家字段解析

                            this.finClosingTemplateService.updateFinClosingTemplate(template);
                            // 首次处理该模板时，删除旧记录
                            String templateIdStr = String.valueOf(template.getId());
                            if (!processedAmazonTemplates.contains(templateIdStr)) {
                                FinClosingTemplateAmazon deleteQuery = new FinClosingTemplateAmazon();
                                deleteQuery.setClosingTemplateId(template.getId());
                                List<FinClosingTemplateAmazon> oldList = finClosingTemplateAmazonService.selectFinClosingTemplateAmazonList(deleteQuery);
                                if (oldList != null && !oldList.isEmpty()) {
                                    List<String> ids = oldList.stream().map(FinClosingTemplateAmazon::getId).collect(Collectors.toList());
                                    finClosingTemplateAmazonService.deleteFinClosingTemplateAmazonByIds(ids);
                                    System.out.println("删除亚马逊模板 " + template.getName() + " 的旧记录 " + ids.size() + " 条");
                                }
                                processedAmazonTemplates.add(templateIdStr);
                            }

                            // 创建亚马逊报表配置
                            FinClosingTemplateAmazon amazon = new FinClosingTemplateAmazon();
                            amazon.setClosingTemplateId(template.getId());
                            amazon.setSummary(amazonColumnMap.containsKey("摘要") ? getCellStringValue(row.getCell(amazonColumnMap.get("摘要"))) : null);
                            // 根据科目编码查询科目ID
                            String subjectCode = amazonColumnMap.containsKey("科目编码") ? getCellStringValue(row.getCell(amazonColumnMap.get("科目编码"))) : null;
                            System.out.println("科目编码: " + subjectCode);
                            if (subjectCode != null && !subjectCode.isEmpty()) {
                                FinAccountingSubjects subjectQuery = new FinAccountingSubjects();
                                subjectQuery.setGroupid(groupid);
                                subjectQuery.setSubjectCode(subjectCode);
                                List<FinAccountingSubjects> subjectList = finAccountingSubjectsMapper.selectFinAccountingSubjectsList(subjectQuery);
                                if (subjectList != null && !subjectList.isEmpty()) {
                                    amazon.setSubjectId(String.valueOf(subjectList.get(0).getSubjectId()));
                                    System.out.println("科目ID: " + subjectList.get(0).getSubjectId());
                                }
                            }
                            amazon.setAmountField(amazonColumnMap.containsKey("金额字段") ? getCellStringValue(row.getCell(amazonColumnMap.get("金额字段"))) : null);

                            // 方向：借方->1，贷方->2
                            String direction = amazonColumnMap.containsKey("方向") ? getCellStringValue(row.getCell(amazonColumnMap.get("方向"))) : null;
                            amazon.setDirection("借方".equals(direction) ? 1 : "贷方".equals(direction) ? 2 : null);
                            amazon.setCreateBy(UserInfoContext.get().getUserName());
                            amazon.setCreatedTime(new Date());
                            amazon.setModifyBy(UserInfoContext.get().getUserName());
                            amazon.setUpdatedTime(new Date());

                            finClosingTemplateAmazonService.insertFinClosingTemplateAmazon(amazon);
                            totalCount++;
                            System.out.println("成功导入亚马逊报表第" + i + "行");
                        } catch (Exception e) {
                            System.out.println("导入亚马逊报表第" + i + "行失败: " + e.getMessage());
                            e.printStackTrace();
                            errors.add("亚马逊报表第" + (i + 1) + "行: " + e.getMessage());
                        }
                    }
                }
            }

            // 处理其他自定义页签
            Sheet otherSheet = workbook.getSheet("其他自定义");
            if (otherSheet != null && otherSheet.getLastRowNum() > 0) {
                // 解析表头，获取列索引
                Row otherHeaderRow = otherSheet.getRow(0);
                if (otherHeaderRow != null) {
                    Map<String, Integer> otherColumnMap = new HashMap<>();
                    for (int j = 0; j < otherHeaderRow.getLastCellNum(); j++) {
                        String header = getCellStringValue(otherHeaderRow.getCell(j));
                        if (header != null) {
                            String key = header.contains("(") ? header.substring(0, header.indexOf("(")) : header;
                            otherColumnMap.put(key, j);
                        }
                    }

                    Set<String> processedOtherTemplates = new HashSet<>();
                    for (int i = 1; i <= otherSheet.getLastRowNum(); i++) {
                        Row row = otherSheet.getRow(i);
                        if (row == null) continue;

                        try {
                            Integer templateNameIdx = otherColumnMap.get("模板名称");
                            String templateName = templateNameIdx != null ? getCellStringValue(row.getCell(templateNameIdx)) : null;
                            if (templateName == null || templateName.isEmpty()) continue;

                            FinClosingTemplate template = findOrCreateTemplate(templateName, "other", groupid, null);

                            // 首次处理该模板时，删除旧记录
                            String templateIdStr = String.valueOf(template.getId());
                            if (!processedOtherTemplates.contains(templateIdStr)) {
                                FinClosingTemplateItem deleteQuery = new FinClosingTemplateItem();
                                deleteQuery.setClosingTemplateId(template.getId());
                                List<FinClosingTemplateItem> oldList = finClosingTemplateItemService.selectFinClosingTemplateItemList(deleteQuery);
                                if (oldList != null && !oldList.isEmpty()) {
                                    List<String> ids = oldList.stream().map(FinClosingTemplateItem::getId).collect(Collectors.toList());
                                    finClosingTemplateItemService.deleteFinClosingTemplateItemByIds(ids);
                                    System.out.println("删除其他自定义模板 " + template.getName() + " 的旧记录 " + ids.size() + " 条");
                                }
                                processedOtherTemplates.add(templateIdStr);
                            }

                            // 创建其他自定义配置
                            FinClosingTemplateItem item = new FinClosingTemplateItem();
                            item.setClosingTemplateId(template.getId());
                            item.setSummary(otherColumnMap.containsKey("摘要") ? getCellStringValue(row.getCell(otherColumnMap.get("摘要"))) : null);
                            // 根据科目编码查询科目ID
                            String subjectCode = otherColumnMap.containsKey("科目编码") ? getCellStringValue(row.getCell(otherColumnMap.get("科目编码"))) : null;
                            if (subjectCode != null && !subjectCode.isEmpty()) {
                                FinAccountingSubjects subjectQuery = new FinAccountingSubjects();
                                subjectQuery.setGroupid(groupid);
                                subjectQuery.setSubjectCode(subjectCode);
                                List<FinAccountingSubjects> subjectList = finAccountingSubjectsMapper.selectFinAccountingSubjectsList(subjectQuery);
                                if (subjectList != null && !subjectList.isEmpty()) {
                                    item.setSubjectId(String.valueOf(subjectList.get(0).getSubjectId()));
                                }
                            }
                            item.setAmountField(otherColumnMap.containsKey("金额字段") ? getCellStringValue(row.getCell(otherColumnMap.get("金额字段"))) : null);
                            // 方向：借方->1，贷方->2
                            String direction = otherColumnMap.containsKey("方向") ? getCellStringValue(row.getCell(otherColumnMap.get("方向"))) : null;
                            item.setDirection("借方".equals(direction) ? 1 : "贷方".equals(direction) ? 2 : null);
                            item.setCreateBy(UserInfoContext.get().getUserName());
                            item.setCreatedTime(new Date());
                            item.setModifyBy(UserInfoContext.get().getUserName());
                            item.setUpdatedTime(new Date());

                            finClosingTemplateItemService.insertFinClosingTemplateItem(item);
                            totalCount++;
                        } catch (Exception e) {
                            errors.add("其他自定义第" + (i + 1) + "行: " + e.getMessage());
                        }
                    }
                }
            }

            // 处理飞书表格页签
            Sheet feishuSheet = workbook.getSheet("飞书表格");
            System.out.println("飞书表格页签: " + (feishuSheet != null ? "存在" : "不存在"));
            if (feishuSheet != null) {
                System.out.println("飞书表格行数: " + feishuSheet.getLastRowNum());
            }
            if (feishuSheet != null && feishuSheet.getLastRowNum() > 0) {
                // 解析表头，获取列索引
                Row feishuHeaderRow = feishuSheet.getRow(0);
                if (feishuHeaderRow != null) {
                    Map<String, Integer> feishuColumnMap = new HashMap<>();
                    for (int j = 0; j < feishuHeaderRow.getLastCellNum(); j++) {
                        String header = getCellStringValue(feishuHeaderRow.getCell(j));
                        if (header != null) {
                            String key = header.contains("(") ? header.substring(0, header.indexOf("(")) : header;
                            feishuColumnMap.put(key, j);
                            System.out.println("飞书表格列: " + key + " -> " + j);
                        }
                    }

                    Set<String> processedFeishuTemplates = new HashSet<>();
                    for (int i = 1; i <= feishuSheet.getLastRowNum(); i++) {
                        Row row = feishuSheet.getRow(i);
                        if (row == null) continue;

                        try {
                            Integer templateNameIdx = feishuColumnMap.get("模板名称");
                            String templateName = templateNameIdx != null ? getCellStringValue(row.getCell(templateNameIdx)) : null;
                            System.out.println("飞书表格第" + i + "行模板名称: " + templateName);
                            if (templateName == null || templateName.isEmpty()) continue;

                            FinClosingTemplate template = findOrCreateTemplate(templateName, "feishu", groupid, null);
                            System.out.println("找到模板: " + template.getName() + ", ID: " + template.getId());

                            // 首次处理该模板时，删除旧的映射配置
                            String templateIdStr = String.valueOf(template.getId());
                            if (!processedFeishuTemplates.contains(templateIdStr)) {
                                FinClosingTemplateItem deleteQuery = new FinClosingTemplateItem();
                                deleteQuery.setClosingTemplateId(template.getId());
                                List<FinClosingTemplateItem> oldItems = finClosingTemplateItemService.selectFinClosingTemplateItemList(deleteQuery);
                                if (oldItems != null && !oldItems.isEmpty()) {
                                    List<String> ids = oldItems.stream().map(FinClosingTemplateItem::getId).collect(Collectors.toList());
                                    finClosingTemplateItemService.deleteFinClosingTemplateItemByIds(ids);
                                    System.out.println("删除飞书模板 " + template.getName() + " 的旧映射配置 " + ids.size() + " 条");
                                }
                                processedFeishuTemplates.add(templateIdStr);
                            }

                            // 创建或更新飞书表格配置
                            FinClosingTemplateFeishu feishuConfig = finClosingTemplateFeishuService.selectFinClosingTemplateFeishuByTemplateid(template.getId());
                            if (feishuConfig == null) {
                                feishuConfig = new FinClosingTemplateFeishu();
                                feishuConfig.setTemplateid(template.getId());
                                // 表格名称需要通过feign调用查找ID
                                String tableName = feishuColumnMap.containsKey("表格名称") ? getCellStringValue(row.getCell(feishuColumnMap.get("表格名称"))) : null;
                                if (tableName != null && !tableName.isEmpty()) {
                                    Long tableId = findFeishuTableIdByName(tableName);
                                    if (tableId != null) {
                                        feishuConfig.setFeishuTableId(String.valueOf(tableId));
                                    } else {
                                        errors.add("飞书表格第" + (i + 1) + "行: 未找到表格 '" + tableName + "'");
                                        continue;
                                    }
                                }
                                feishuConfig.setSummaryField(feishuColumnMap.containsKey("摘要字段") ? getCellStringValue(row.getCell(feishuColumnMap.get("摘要字段"))) : null);
                                feishuConfig.setVoucherDateField(feishuColumnMap.containsKey("日期字段") ? getCellStringValue(row.getCell(feishuColumnMap.get("日期字段"))) : null);
                                feishuConfig.setSubjectField(feishuColumnMap.containsKey("科目字段") ? getCellStringValue(row.getCell(feishuColumnMap.get("科目字段"))) : null);
                                feishuConfig.setAmountField(feishuColumnMap.containsKey("金额字段") ? getCellStringValue(row.getCell(feishuColumnMap.get("金额字段"))) : null);
                                // 汇总方式：按日->0，按月->1，单笔生成凭证->2
                                String datetype = feishuColumnMap.containsKey("汇总方式") ? getCellStringValue(row.getCell(feishuColumnMap.get("汇总方式"))) : null;
                                feishuConfig.setDatetype("按日".equals(datetype) ? 0 : "按月".equals(datetype) ? 1 : "单笔生成凭证".equals(datetype) ? 2 : null);
                                feishuConfig.setFilter(feishuColumnMap.containsKey("过滤条件") ? getCellStringValue(row.getCell(feishuColumnMap.get("过滤条件"))) : null);
                                finClosingTemplateFeishuService.insertFinClosingTemplateFeishu(feishuConfig);
                            } else {
                                // 更新现有配置
                                String tableName = feishuColumnMap.containsKey("表格名称") ? getCellStringValue(row.getCell(feishuColumnMap.get("表格名称"))) : null;
                                if (tableName != null && !tableName.isEmpty()) {
                                    Long tableId = findFeishuTableIdByName(tableName);
                                    if (tableId != null) {
                                        feishuConfig.setFeishuTableId(String.valueOf(tableId));
                                    }
                                }
                                feishuConfig.setSummaryField(feishuColumnMap.containsKey("摘要字段") ? getCellStringValue(row.getCell(feishuColumnMap.get("摘要字段"))) : null);
                                feishuConfig.setVoucherDateField(feishuColumnMap.containsKey("日期字段") ? getCellStringValue(row.getCell(feishuColumnMap.get("日期字段"))) : null);
                                feishuConfig.setSubjectField(feishuColumnMap.containsKey("科目字段") ? getCellStringValue(row.getCell(feishuColumnMap.get("科目字段"))) : null);
                                feishuConfig.setAmountField(feishuColumnMap.containsKey("金额字段") ? getCellStringValue(row.getCell(feishuColumnMap.get("金额字段"))) : null);
                                // 汇总方式：按日->0，按月->1，单笔生成凭证->2
                                String datetype = feishuColumnMap.containsKey("汇总方式") ? getCellStringValue(row.getCell(feishuColumnMap.get("汇总方式"))) : null;
                                feishuConfig.setDatetype("按日".equals(datetype) ? 0 : "按月".equals(datetype) ? 1 : "单笔生成凭证".equals(datetype) ? 2 : null);
                                feishuConfig.setFilter(feishuColumnMap.containsKey("过滤条件") ? getCellStringValue(row.getCell(feishuColumnMap.get("过滤条件"))) : null);
                                finClosingTemplateFeishuService.updateFinClosingTemplateFeishu(feishuConfig);
                            }

                            // 处理会计科目映射配置
                            String debitCode = feishuColumnMap.containsKey("借方科目编码") ? getCellStringValue(row.getCell(feishuColumnMap.get("借方科目编码"))) : null;
                            String creditCode = feishuColumnMap.containsKey("贷方科目编码") ? getCellStringValue(row.getCell(feishuColumnMap.get("贷方科目编码"))) : null;
                            String contentMatch = feishuColumnMap.containsKey("内容配对") ? getCellStringValue(row.getCell(feishuColumnMap.get("内容配对"))) : null;
                            System.out.println("飞书映射配置 - 借方: " + debitCode + ", 贷方: " + creditCode + ", 内容配对: " + contentMatch);

                            if ((debitCode != null && !debitCode.isEmpty()) || (creditCode != null && !creditCode.isEmpty()) || (contentMatch != null && !contentMatch.isEmpty())) {
                                // 根据科目编码查询科目ID
                                String debitSubjectId = null;
                                String creditSubjectId = null;
                                if (debitCode != null && !debitCode.isEmpty()) {
                                    FinAccountingSubjects subjectQuery = new FinAccountingSubjects();
                                    subjectQuery.setGroupid(groupid);
                                    subjectQuery.setSubjectCode(debitCode);
                                    List<FinAccountingSubjects> subjectList = finAccountingSubjectsMapper.selectFinAccountingSubjectsList(subjectQuery);
                                    if (subjectList != null && !subjectList.isEmpty()) {
                                        debitSubjectId = String.valueOf(subjectList.get(0).getSubjectId());
                                    }
                                }
                                if (creditCode != null && !creditCode.isEmpty()) {
                                    FinAccountingSubjects subjectQuery = new FinAccountingSubjects();
                                    subjectQuery.setGroupid(groupid);
                                    subjectQuery.setSubjectCode(creditCode);
                                    List<FinAccountingSubjects> subjectList = finAccountingSubjectsMapper.selectFinAccountingSubjectsList(subjectQuery);
                                    if (subjectList != null && !subjectList.isEmpty()) {
                                        creditSubjectId = String.valueOf(subjectList.get(0).getSubjectId());
                                    }
                                }

                                // 创建会计科目映射（旧记录已删除）
                                FinClosingTemplateItem item = new FinClosingTemplateItem();
                                item.setClosingTemplateId(template.getId());

                                if (debitSubjectId != null) {
                                    item.setSummary(debitSubjectId);
                                }
                                if (creditSubjectId != null) {
                                    item.setSubjectId(creditSubjectId);
                                }
                                item.setAmountField(contentMatch);
                                item.setCreateBy(UserInfoContext.get().getUserName());
                                item.setCreatedTime(new Date());
                                item.setModifyBy(UserInfoContext.get().getUserName());
                                item.setUpdatedTime(new Date());

                                finClosingTemplateItemService.insertFinClosingTemplateItem(item);
                            }

                            totalCount++;
                            System.out.println("成功导入飞书表格第" + i + "行");
                        } catch (Exception e) {
                            System.out.println("导入飞书表格第" + i + "行失败: " + e.getMessage());
                            e.printStackTrace();
                            errors.add("飞书表格第" + (i + 1) + "行: " + e.getMessage());
                        }
                    }
                }
            }

            if (!errors.isEmpty()) {
                return Result.error("导入完成，但有部分错误:\n" + String.join("\n", errors));
            }

            return Result.success("导入成功，共导入 " + totalCount + " 条数据");
        }
    }

@Override
	public void handlerResult(AmazonAuthority auth, AmzProductRefreshType skuRefresh,Item result) {
		log.info("handlerResult开始执行, authId={}, sku={}, asin={}, pid={}", 
				auth.getId(), skuRefresh.getSku(), skuRefresh.getAsin(), skuRefresh.getPid());
	   if(result==null) {
		   log.warn("handlerResult: result为null，直接返回, authId={}, sku={}", auth.getId(), skuRefresh.getSku());
		   return;
	   }
       ItemRelationships relist = result.getRelationships();
       log.info("handlerResult: relist={}, authId={}, sku={}", relist == null ? "null" : "size=" + relist.size(), auth.getId(), skuRefresh.getSku());
       // 如果pid未设置，通过sku查询产品信息获取pid
       if(skuRefresh.getPid()==null) {
    	   ProductInfo baseInfo = iProductInfoService.productOnlyone(auth.getId(), skuRefresh.getSku(), skuRefresh.getMarketplaceid());
    	   if(baseInfo!=null) {
    		   skuRefresh.setPid(new BigInteger(baseInfo.getId()));
    		   log.info("handlerResult: pid为空，通过sku查询补全pid={}", skuRefresh.getPid());
    	   } else {
    		   log.warn("handlerResult: pid为空且通过sku查询不到商品, authId={}, sku={}", auth.getId(), skuRefresh.getSku());
    	   }
       }
       // API调用成功，更新刷新时间（无论是否有relationships）
       if(skuRefresh.getPid()!=null) {
    	   boolean updated = iAmzProductRefreshTypeService.updateRefreshTime(
    			   skuRefresh.getPid().toString(), AmzProductRefreshType.TYPE_CATALOG, LocalDateTime.now());
    	   log.info("handlerResult: updateRefreshTime结果={}, pid={}, authId={}", updated, skuRefresh.getPid(), auth.getId());
       } else {
    	   log.warn("handlerResult: pid仍为null，无法更新refresh_time, authId={}, sku={}", auth.getId(), skuRefresh.getSku());
       }
       if(relist==null) {
    	   log.info("handlerResult: relist为null，跳过后续处理, authId={}, sku={}", auth.getId(), skuRefresh.getSku());
    	   return;
       }
       for(ItemRelationshipsByMarketplace relations:relist) {
    	  String marketplaceid= relations.getMarketplaceId();
    	    for(ItemRelationship rela:relations.getRelationships()) {
    	    	List<String> parentAsins = rela.getParentAsins();
    	    	List<String> children = rela.getChildAsins();
    	    	ProductInfo info = iProductInfoService.productOnlyone(auth.getId(),skuRefresh.getSku(),  marketplaceid);
    	    	if(info==null) {continue;}
    	    	if(parentAsins!=null&&parentAsins.size()>0) {
    	    		for(String parentAsin:parentAsins) {
        	    		if(StrUtil.isNotBlank(parentAsin)) {
            	    		if(info.getParentAsin()==null||!info.getParentAsin().equals(parentAsin)||Boolean.TRUE.equals(info.getIsparent())) {
            	    			info.setParentAsin(parentAsin);
            	    			info.setParentMarketplace(marketplaceid);
            	    			info.setIsparent(false);
            	    			iProductInfoService.updateById(info);
            	    			List<ProductInfo> asinParent = iProductInfoService.selectByAsin(auth.getId(), parentAsin ,marketplaceid);
            	    			if(asinParent!=null) {
            	    				for(ProductInfo parent:asinParent) {
										if(parent.getParentAsin()==null){
											parent.setIsparent(true);
											iProductInfoService.updateById(parent);
										}
                	    			}
            	    			}
            	    		}
            	    	}
        	    	}
    	    	}
    	    	else if(children!=null&&children.size()>0) {
    	    		boolean isparent = false;
    	    		for(String child:children) {
        	    		if(StrUtil.isNotBlank(child)) {
        	    			  List<ProductInfo> asinChildren = iProductInfoService.selectByAsin(auth.getId(), child ,marketplaceid);
            	    		  if(asinChildren!=null && asinChildren.size()>0) {
            	    			  for(ProductInfo childInfo:asinChildren) {
                	    			  if(childInfo.getParentAsin()==null||!childInfo.getParentAsin().equals(info.getAsin())) {
                	    				  childInfo.setParentAsin(info.getAsin());
                	    				  childInfo.setParentMarketplace(marketplaceid);
                	    				  childInfo.setIsparent(false);
                      	    			  iProductInfoService.updateById(childInfo);
                      	    		  }
                	    			  isparent=true;
                	    		  }
            	    		  }
            	    	}
        	    	}
    	    		if(isparent&&StrUtil.isBlank(info.getParentAsin())) {
    	    			if(info.getIsparent()==null||!info.getIsparent()) {
    	    				info.setIsparent(true);
    	    				iProductInfoService.updateById(info);
    	    			}
    	    		}
    	    	}

    	    }
       }
       ItemSalesRanks salesRanks = result.getSalesRanks();
       if(salesRanks!=null) {
           for(ItemSalesRanksByMarketplace itemSalesRanksByMarketplace:salesRanks) {
        	   String marketplaceid= itemSalesRanksByMarketplace.getMarketplaceId();
    	       ProductInfo info = iProductInfoService.productOnlyone(auth.getId(),skuRefresh.getSku(),  marketplaceid);
    	       if(info==null) {continue;}
    	       List<ItemClassificationSalesRank> classificationRanks = itemSalesRanksByMarketplace.getClassificationRanks();
    	       List<ItemDisplayGroupSalesRank> displayGroupRanks = itemSalesRanksByMarketplace.getDisplayGroupRanks();
    	       for(ItemClassificationSalesRank itemClassificationSalesRank:classificationRanks) {
    	    	   Integer rank = itemClassificationSalesRank.getRank();
    	    	   //String link=itemClassificationSalesRank.getLink();
    	    	   String categoryId=itemClassificationSalesRank.getClassificationId();
    	    	   //String title=itemClassificationSalesRank.getTitle();
    	    	   ProductRank productRank=new ProductRank();
    	    	   productRank.setByday(new Date());
    	    	   productRank.setCategoryid(categoryId);
    	    	   productRank.setIsmain(false);
    	    	   productRank.setRank(rank);
    	    	   productRank.setTitle(itemClassificationSalesRank.getTitle());
    	    	   productRank.setLink(itemClassificationSalesRank.getLink());
    	    	   productRank.setProductId(info.getId());
    	    	   iProductRankService.insert(productRank);
    	       }
    	       for(ItemDisplayGroupSalesRank itemDisplayGroupSalesRank:displayGroupRanks) {
    	    	   //String  link=itemDisplayGroupSalesRank.getLink();
    	    	   Integer rank = itemDisplayGroupSalesRank.getRank();
    	    	   //String title=itemDisplayGroupSalesRank.getTitle();
    	    	   String categoryId=itemDisplayGroupSalesRank.getWebsiteDisplayGroup();
    	    	   ProductRank productRank=new ProductRank();
    	    	   productRank.setByday(new Date());
    	    	   productRank.setCategoryid(categoryId);
    	    	   productRank.setIsmain(true);
    	    	   productRank.setRank(rank);
    	    	   productRank.setTitle(itemDisplayGroupSalesRank.getTitle());
    	    	   productRank.setLink(itemDisplayGroupSalesRank.getLink());
    	    	   productRank.setProductId(info.getId());
    	    	   iProductRankService.insert(productRank);
    	       }
           }
       }
		ItemDimensions dimensions= result.getDimensions();
		if(dimensions!=null && !dimensions.isEmpty()){
			for(ItemDimensionsByMarketplace dim:dimensions){
				ProductInfo info = iProductInfoService.productOnlyone(auth.getId(),skuRefresh.getSku(),  dim.getMarketplaceId());
				if(info==null) {continue;}
				if(dim.getItem()!= null){
					DimensionsInfo item=new DimensionsInfo();
					if(  dim.getItem().getLength()!=null){
						item.setLength(dim.getItem().getLength().getValue());
						item.setLengthUnits(dim.getItem().getLength().getUnit());
					}
					if(dim.getItem().getWidth()!=null){
						item.setWidth(dim.getItem().getWidth().getValue());
						item.setWidthUnits(dim.getItem().getWidth().getUnit());
					}
					if(dim.getItem().getHeight()!=null){
						item.setHeight(dim.getItem().getHeight().getValue());
						item.setHeightUnits(dim.getItem().getHeight().getUnit());
					}
					if(dim.getItem().getWeight()!=null){
						item.setWeight(dim.getItem().getWeight().getValue());
						item.setWeightUnits(dim.getItem().getWeight().getUnit());
					}
					dimensionsInfoMapper.insert(item);
					info.setItemDimensions(new BigInteger(item.getId()));
				}
				if(dim.getPackage()!=null && dim.getPackage().getLength()!=null){
					DimensionsInfo item=new DimensionsInfo();
					if(dim.getPackage().getLength()!=null){
						item.setLength(dim.getPackage().getLength().getValue());
						item.setLengthUnits(dim.getPackage().getLength().getUnit());
					}
					if(dim.getPackage().getWidth()!=null){
						item.setWidth(dim.getPackage().getWidth().getValue());
						item.setWidthUnits(dim.getPackage().getWidth().getUnit());
					}
					if(dim.getPackage().getHeight()!=null){
						item.setHeight(dim.getPackage().getHeight().getValue());
						item.setHeightUnits(dim.getPackage().getHeight().getUnit());
					}
					if(dim.getPackage().getWeight()!=null){
						item.setWeight(dim.getPackage().getWeight().getValue());
						item.setWeightUnits(dim.getPackage().getWeight().getUnit());
					}
					dimensionsInfoMapper.insert(item);
					info.setPageDimensions(new BigInteger(item.getId()));
				}
				iProductInfoService.updateById(info);
			}


		}
       ItemSummaries summary = result.getSummaries();
       String imageurl = null;
	if(summary!=null&&summary.size()>0) {
    	   for(ItemSummaryByMarketplace item:summary) {
    		   String brand=null;
    		   String manufacturer=null;
    		   if(item.getBrand()!=null) {
    			   brand=item.getBrand();
    		   }
    		   if(item.getManufacturer()!=null) {
    			   manufacturer=item.getManufacturer();
    		   }
			   ProductInfo info = iProductInfoService.productOnlyone(auth.getId(),skuRefresh.getSku(),  item.getMarketplaceId());
			   if(info==null) {
				   continue;
			   }
			   if(info.getName()==null) {
				   info.setName(item.getItemName());
			   }
		       info.setBrand(brand);
		       if(result.getProductTypes()!=null&&result.getProductTypes().size()>0) {
		    	   info.setTypename(result.getProductTypes().get(0).getProductType());
		       }
		       info.setManufacturer(manufacturer);
		       if(result.getImages()!=null&&result.getImages().size()>0) {
					ItemImagesByMarketplace image = result.getImages().get(0);
					List<ItemImage> images = image.getImages();
					if(images!=null&&images.size()>0) {
						for(ItemImage itemimage:images) {
							if(itemimage.getVariant().compareTo(VariantEnum.MAIN)==0&&itemimage.getWidth()==75) {
								imageurl=itemimage.getLink();
								break;
							}
						}
					}
					Picture picture=null;
				    try {
				    	if(imageurl!=null) {
				    		if(info.getImage()!=null) {
					    		picture=pictureService.getById(info.getImage());
					    		if(picture==null
					    				||picture.getUrl()==null
					    				||picture.getLocation()==null
					    				||!picture.getUrl().equals(imageurl)
					    				) {
					    			if(picture!=null&&picture.getUrl()!=null&&!picture.getUrl().equals(imageurl)){
					    				String path=PictureServiceImpl.productImgPath+auth.getShopId()+"/"+auth.getId()+"/"+info.getMarketplaceid()+"/";
						    			picture=pictureService.downloadPicture(imageurl,path, info.getImage().toString());
						    			manufacturer =manufacturer!=null?manufacturer:"";
						    			info.setManufacturer(manufacturer+"-c");
					    			}
					    			if(picture!=null&&picture.getOpttime()!=null&&GeneralUtil.distanceOfDay(picture.getOpttime(), new Date())<3) {
					    				 //do nothing
					    			}else {
					    				String path=PictureServiceImpl.productImgPath+auth.getShopId()+"/"+auth.getId()+"/"+info.getMarketplaceid()+"/";
						    			picture=pictureService.downloadPicture(imageurl,path, info.getImage().toString());
						    			manufacturer =manufacturer!=null?manufacturer:"";
						    			info.setManufacturer(manufacturer+"-c");
					    			}


					    		}
					    	}else {
					    		String path=PictureServiceImpl.productImgPath+auth.getShopId()+"/"+auth.getId()+"/"+info.getMarketplaceid()+"/";
					    		picture=pictureService.downloadPicture(imageurl, path,null);
					    		manufacturer =manufacturer!=null?manufacturer:"";
				    			info.setManufacturer(manufacturer+"-c");
					    	}
				    	}
				    	 if(picture!=null) {
			    		       	info.setImage(new BigInteger(picture.getId()));
			    		  }
					} catch (Exception e) {
						// TODO Auto-generated catch block
						e.printStackTrace();
					}
				}
		       iProductInfoService.updateById(info);
    	   }
       }



	}

@Override
    public SseEmitter completionsAgentStream(UserInfo userInfo, SysChartCompletionRequestDTO dto) {
        log.info("[Agent] 开始处理Agent流式请求, sessionId={}, userId={}", dto.getSessionId(), userInfo.getId());
        SseEmitter emitter = new SseEmitter(600000L); // 10分钟超时

        // 在主线程获取用户可访问的菜单ID集合（避免异步线程中数据库上下文问题）
        final Set<Integer> allowedMenuIds = getUserAllowedMenuIds(userInfo);
        log.info("[Agent] 用户可访问菜单数: {}", allowedMenuIds != null ? allowedMenuIds.size() : "全部");

        // 捕获当前线程的Shiro上下文，传播到异步线程
        org.apache.shiro.mgt.SecurityManager securityManager = null;
        Subject subject = null;
        try {
            securityManager = SecurityUtils.getSecurityManager();
            subject = SecurityUtils.getSubject();
        } catch (Exception e) {
            log.warn("获取Shiro上下文失败，将不传播Shiro上下文: {}", e.getMessage());
        }

        // 保存最终值用于lambda表达式
        final org.apache.shiro.mgt.SecurityManager finalSecurityManager = securityManager;
        final Subject finalSubject = subject;

        log.info("[Agent] 提交异步任务到线程池");
        executorService.execute(() -> {
            log.info("[Agent] 异步任务开始执行");
            try {
                // 绑定Shiro上下文到异步线程
                if (finalSecurityManager != null) {
                    ThreadContext.bind(finalSecurityManager);
                }
                if (finalSubject != null) {
                    ThreadContext.bind(finalSubject);
                }
                // 立即发送"正在准备"状态事件，让用户知道后端已开始处理
                sendStatusEvent(emitter, "preparing", "正在准备中...");

                // 构建消息列表
                List<JSONObject> messages = new ArrayList<>();

                // 添加系统提示词，告诉AI它是一个ERP系统助手
                sendStatusEvent(emitter, "loading", "正在加载系统配置...");
                JSONObject systemMessage = new JSONObject();
                systemMessage.put("role", "system");
                systemMessage.put("content", buildAgentSystemPrompt(userInfo, allowedMenuIds, dto.getCurrentPage(), dto.getPageTitle(), dto.getHelpDocUrl(), dto.getHelpDocLibrary(), dto.getCurrentHelpDoc()));
                messages.add(systemMessage);

                // 获取历史消息（验证会话归属当前用户，防止跨租户访问）
                if (StrUtil.isNotBlank(dto.getSessionId())) {
                    sendStatusEvent(emitter, "loading", "正在加载历史消息...");
                    DeepseekChatSessions existingSession = iDeepseekChatSessionsService.lambdaQuery()
                            .eq(DeepseekChatSessions::getId, dto.getSessionId())
                            .eq(DeepseekChatSessions::getUserid, userInfo.getId())
                            .one();
                    if (existingSession == null) {
                        throw new RuntimeException("会话不存在或无权访问");
                    }
                    List<DeepseekChatMessages> historyMessages = iDeepseekChatMessagesService.lambdaQuery()
                            .eq(DeepseekChatMessages::getSessionId, dto.getSessionId())
                            .orderBy(true, true, DeepseekChatMessages::getCreatetime)
                            .list();
                    // 只保留最近的20条历史消息，避免历史消息过多导致AI依赖历史结果
                    int startIndex = Math.max(0, historyMessages.size() - 20);
                    for (int i = startIndex; i < historyMessages.size(); i++) {
                        DeepseekChatMessages message = historyMessages.get(i);
                        JSONObject msg = new JSONObject();
                        msg.put("role", message.getRole());
                        msg.put("content", message.getContent());
                        messages.add(msg);
                    }
                }

                // 添加新消息
                List<DeepseekChatMessages> newMessages = new ArrayList<>();
                for (DeepSeekMessage message : dto.getMessages()) {
                    DeepseekChatMessages e = new DeepseekChatMessages();
                    e.setSessionId(dto.getSessionId());
                    e.setCreatetime(new Date());
                    e.setContent(message.getContent());
                    e.setRole(message.getRole());
                    newMessages.add(e);

                    JSONObject msg = new JSONObject();
                    msg.put("role", message.getRole());
                    msg.put("content", message.getContent());
                    messages.add(msg);
                }

                // 获取工具定义
                sendStatusEvent(emitter, "loading", "正在加载工具定义...");
                List<JSONObject> tools = AgentTools.getAllTools();
                log.info("[Agent] 加载了{}个工具定义", tools.size());
                sendStatusEvent(emitter, "ready", String.format("已加载%d个工具，准备就绪", tools.size()));

                String sessionId = dto.getSessionId();
                int maxIterations = 15; // 最大循环次数，防止无限循环
                int iteration = 0;
                int toolCallRoundCount = 0; // 已执行工具调用的轮次计数
                StringBuilder fullContent = new StringBuilder();

                // 第一阶段：让AI选择需要使用的工具（按菜单权限过滤）
                sendStatusEvent(emitter, "selecting_tools", "正在分析问题，选择合适的工具...");
                List<JSONObject> toolSummaries = AgentTools.getToolSummaries(allowedMenuIds);
                List<String> selectedToolNames = selectToolsWithAI(messages, toolSummaries, dto.getModel());
                log.info("[Agent] AI选择了{}个工具: {}", selectedToolNames.size(), selectedToolNames);

                if (selectedToolNames.isEmpty()) {
                    // AI没有选择任何工具，直接告知用户没有相关权限
                    sendStatusEvent(emitter, "thinking", "AI正在思考中...");
                    String directContent;
                    // 检查用户是否在询问业务数据（关键词匹配）
                    String userQuestion = dto.getMessages() != null && !dto.getMessages().isEmpty() ?
                            dto.getMessages().get(dto.getMessages().size() - 1).getContent() : "";
                    if (containsBusinessKeyword(userQuestion)) {
                        directContent = "抱歉，您没有查询该数据的权限。如需开通相关功能，请联系管理员。";
                    } else {
                        JSONObject directResponse = callAIWithoutTools(messages, dto.getModel());
                        directContent = directResponse.getString("content");
                        if (StrUtil.isBlank(directContent)) {
                            directContent = "抱歉，我无法理解您的问题。请尝试重新描述您的问题。";
                        }
                    }
                    fullContent.append(directContent);
                    JSONObject contentEvent = new JSONObject();
                    contentEvent.put("content", directContent);
                    emitter.send(SseEmitter.event()
                            .id(String.valueOf(System.currentTimeMillis()))
                            .data(contentEvent.toJSONString(), org.springframework.http.MediaType.APPLICATION_JSON));
                } else {
                    // 第二阶段：使用提示词驱动的方式调用工具（不依赖function calling）
                    String toolPrompt = AgentTools.buildToolPromptForNames(selectedToolNames);
                    sendStatusEvent(emitter, "ready", String.format("已选择%d个工具，开始处理", selectedToolNames.size()));

                    // Agent循环
                    while (iteration < maxIterations) {
                        iteration++;
                        log.info("[Agent] 第{}轮循环开始", iteration);

                        // 发送"正在思考"状态事件
                        sendStatusEvent(emitter, "thinking",
                                iteration == 1 ? "AI正在思考中..." : "AI正在分析工具返回结果...");

                        // 构建带工具定义的提示词
                        List<JSONObject> agentMessages = new ArrayList<>();
                        // 复制原有消息
                        for (JSONObject msg : messages) {
                            agentMessages.add(msg);
                        }

                        // 每轮都添加工具调用指令（确保AI始终记得格式）
                        JSONObject toolInstruction = new JSONObject();
                        toolInstruction.put("role", "system");
                        if (iteration == 1) {
                            toolInstruction.put("content", buildToolCallInstruction(toolPrompt));
                        } else if (toolCallRoundCount >= 2) {
                            // 已经执行过多轮工具调用，强制要求给出最终答案
                            toolInstruction.put("content", "你已经调用了多次工具并获取了足够的数据。现在必须直接输出最终答案给用户，禁止再调用任何工具。用中文清晰地汇总所有已获取的数据，回答用户的问题。");
                        } else {
                            // 后续轮次使用简短提醒
                            toolInstruction.put("content", "重要提醒：\n" +
                                    "- 如果前面的工具调用已经返回了足够数据，你现在必须直接输出最终答案，禁止再调用工具\n" +
                                    "- 只有在缺少关键数据且必须补充时，才可以继续调用工具\n" +
                                    "- 绝对不要重复调用已经调用过的工具\n" +
                                    "- 输出最终答案时，用中文清晰地汇总数据\n" +
                                    "如需调用工具，只输出TOOL_CALL格式；如数据已足够，直接输出最终答案。");
                        }
                        agentMessages.add(toolInstruction);

                        // 使用function calling方式调用AI（支持所有OpenAI兼容模型：qwen/deepseek/kimi/minimax）
                        // 只传递AI选中的工具，而不是全部工具（避免token超限）
                        List<JSONObject> selectedTools = new ArrayList<>();
                        for (JSONObject tool : tools) {
                            JSONObject func = tool.getJSONObject("function");
                            String toolName = func != null ? func.getString("name") : null;
                            if (toolName != null && selectedToolNames.contains(toolName)) {
                                selectedTools.add(tool);
                            }
                        }
                        if (selectedTools.isEmpty()) {
                            log.warn("[Agent] 选中的工具列表为空，跳过本轮工具调用");
                            break;
                        }
                        int msgCount = agentMessages.size();
                        int toolCount = selectedTools.size();
                        log.info("[Agent] 调用AI接口, model={}, tools={}/{}", dto.getModel(), toolCount, tools.size());
                        log.info("[Agent] 调用AI接口: 消息数: {}, 工具数: {}", msgCount, toolCount);
                        sendAgentDetailEvent(emitter, "ai_calling", 
                            "第" + iteration + "轮: 调用AI模型 " + dto.getModel() + " (消息:" + msgCount + ", 工具:" + toolCount + ")");

                        JSONObject aiResponse = callAIWithTools(agentMessages, selectedTools, dto.getModel());
                        String aiContent = aiResponse.getString("content");
                        int respLen = aiContent != null ? aiContent.length() : 0;
                        boolean hasToolCalls = aiResponse.getJSONArray("tool_calls") != null && !aiResponse.getJSONArray("tool_calls").isEmpty();
                        log.info("[Agent] AI接口响应长度: {}", respLen);
                        log.info("[Agent] AI响应成功, hasToolCalls={}", hasToolCalls);
                        log.info("[Agent] AI响应长度: {}", respLen);
                        sendAgentDetailEvent(emitter, "ai_response", 
                            "第" + iteration + "轮: AI响应 " + (respLen > 0 ? "内容" + respLen + "字" : "无内容") + (hasToolCalls ? ", 包含工具调用" : ""));

                        if (aiResponse.containsKey("error")) {
                            String errorMsg = aiResponse.getString("error");
                            log.error("[Agent] AI调用失败: {}", errorMsg);
                            // 不直接break，而是将错误信息作为最终答案返回给用户
                            fullContent.append("AI调用失败: ").append(errorMsg);
                            JSONObject contentEvent = new JSONObject();
                            contentEvent.put("content", "AI调用失败: " + errorMsg);
                            emitter.send(SseEmitter.event()
                                    .id(String.valueOf(System.currentTimeMillis()))
                                    .data(contentEvent.toJSONString(), org.springframework.http.MediaType.APPLICATION_JSON));
                            break;
                        }

                        // 发送AI思考过程到前端（reasoning内容）
                        // kimi-k2-thinking模型使用reasoning_content字段
                        String reasoning = aiResponse.getString("reasoning_content");
                        if (StrUtil.isBlank(reasoning)) {
                            reasoning = aiResponse.getString("reasoning");
                        }
                        if (StrUtil.isNotBlank(reasoning)) {
                            JSONObject reasoningEvent = new JSONObject();
                            reasoningEvent.put("reasoning", reasoning);
                            emitter.send(SseEmitter.event()
                                    .id("reasoning-" + System.currentTimeMillis())
                                    .data(reasoningEvent.toJSONString(), org.springframework.http.MediaType.APPLICATION_JSON));
                        }

                        // 优先检查原生tool_calls（function calling格式）
                        JSONArray nativeToolCalls = aiResponse.getJSONArray("tool_calls");
                        List<JSONObject> parsedToolCalls = new ArrayList<>();

                        if (nativeToolCalls != null && !nativeToolCalls.isEmpty()) {
                            // 原生function calling响应，直接解析tool_calls
                            log.info("[Agent] 检测到原生tool_calls, 数量: {}", nativeToolCalls.size());
                            for (int i = 0; i < nativeToolCalls.size(); i++) {
                                JSONObject tc = nativeToolCalls.getJSONObject(i);
                                JSONObject function = tc.getJSONObject("function");
                                if (function != null) {
                                    JSONObject parsed = new JSONObject();
                                    parsed.put("tool", function.getString("name"));
                                    parsed.put("params", function.getString("arguments"));
                                    parsedToolCalls.add(parsed);
                                }
                            }
                        } else if (StrUtil.isNotBlank(aiContent)) {
                            // 没有原生tool_calls，尝试从文本中解析TOOL_CALL
                            // 检测占位符（如minimax:tool_call）
                            String trimmedContent = aiContent.trim();
                            if (trimmedContent.matches("^[a-zA-Z_-]+:tool_call$") || trimmedContent.contains(":tool_call")) {
                                log.warn("[Agent] 模型返回了tool_call占位符: '{}', iteration={}", trimmedContent, iteration);
                                continue;
                            }
                            parsedToolCalls = parseToolCallsFromText(aiContent);
                        }

                        // 如果既没有tool_calls，content也为空，则跳过本轮
                        if ((parsedToolCalls == null || parsedToolCalls.isEmpty()) && StrUtil.isBlank(aiContent)) {
                            log.warn("[Agent] AI返回空内容且无工具调用, iteration={}", iteration);
                            if (iteration >= maxIterations) {
                                fullContent.append("AI未能生成有效回复，请重试。");
                                JSONObject contentEvent = new JSONObject();
                                contentEvent.put("content", "AI未能生成有效回复，请重试。");
                                emitter.send(SseEmitter.event()
                                        .id(String.valueOf(System.currentTimeMillis()))
                                        .data(contentEvent.toJSONString(), org.springframework.http.MediaType.APPLICATION_JSON));
                            }
                            continue;
                        }

                        if (parsedToolCalls != null && !parsedToolCalls.isEmpty()) {
                            // 有工具调用
                            log.info("[Agent] 解析到{}个工具调用", parsedToolCalls.size());

                            // 提取思考内容（工具调用标记之前的部分）
                            String thinkingContent = extractThinkingContent(aiContent);
                            if (StrUtil.isNotBlank(thinkingContent)) {
                                JSONObject reasoningEvent = new JSONObject();
                                reasoningEvent.put("reasoning", thinkingContent);
                                emitter.send(SseEmitter.event()
                                        .id(String.valueOf(System.currentTimeMillis()))
                                        .data(reasoningEvent.toJSONString(), org.springframework.http.MediaType.APPLICATION_JSON));
                            }

                            // 构建工具调用摘要（不含TOOL_CALL原文，避免混淆AI）
                            StringBuilder toolCallSummary = new StringBuilder();
                            for (JSONObject tc : parsedToolCalls) {
                                toolCallSummary.append("调用工具: ").append(tc.getString("tool")).append("\n");
                            }

                            // 添加AI回复到消息列表（支持原生tool_calls格式）
                            JSONObject assistantMessage = new JSONObject();
                            assistantMessage.put("role", "assistant");
                            if (nativeToolCalls != null && !nativeToolCalls.isEmpty()) {
                                // 原生function calling：保留content和tool_calls
                                assistantMessage.put("content", StrUtil.isNotBlank(aiContent) ? aiContent : "");
                                assistantMessage.put("tool_calls", nativeToolCalls);
                            } else {
                                // 文本解析模式：只保留思考内容
                                String cleanContent = StrUtil.isNotBlank(thinkingContent) ? thinkingContent : toolCallSummary.toString();
                                assistantMessage.put("content", cleanContent);
                            }
                            messages.add(assistantMessage);

                            // 构建已授权工具名称集合，用于二次校验
                            Set<String> allowedToolNameSet = new HashSet<>(selectedToolNames);

                            // 执行所有工具调用（AI可能一次输出多个，只要参数是具体的就全部执行）
                            for (int tcIdx = 0; tcIdx < parsedToolCalls.size(); tcIdx++) {
                                JSONObject toolCall = parsedToolCalls.get(tcIdx);
                                String functionName = toolCall.getString("tool");
                                String functionArgs = toolCall.getString("params");

                                // 权限二次校验：确保工具在第一阶段筛选通过的列表中
                                if (!allowedToolNameSet.contains(functionName)) {
                                    log.warn("[Agent] 工具不在授权列表中，拒绝执行: {}", functionName);
                                    JSONObject denyEvent = new JSONObject();
                                    denyEvent.put("type", "tool_result");
                                    denyEvent.put("function_name", functionName);
                                    denyEvent.put("result", "{\"success\":false,\"error\":\"权限不足：您没有使用该工具的权限。请联系管理员开通相应权限。\"}");
                                    emitter.send(SseEmitter.event()
                                            .id("tool_result_" + System.currentTimeMillis())
                                            .data(denyEvent.toJSONString(), org.springframework.http.MediaType.APPLICATION_JSON));
                                    continue;
                                }

                                // 获取原生tool_call_id（用于function calling格式）
                                String toolCallId = null;
                                if (nativeToolCalls != null && tcIdx < nativeToolCalls.size()) {
                                    toolCallId = nativeToolCalls.getJSONObject(tcIdx).getString("id");
                                }

                                // 获取工具详细信息
                                JSONObject toolInfo = AgentTools.getToolInfo(functionName);

                                // 发送工具调用事件
                                log.info("[Agent] AI请求调用工具: {}, args={}", functionName, functionArgs);
                                JSONObject toolCallEvent = new JSONObject();
                                toolCallEvent.put("type", "tool_call");
                                toolCallEvent.put("function_name", functionName);
                                if (toolInfo != null) {
                                    toolCallEvent.put("function_description", toolInfo.getString("description"));
                                    toolCallEvent.put("endpoint", toolInfo.getString("endpoint"));
                                    toolCallEvent.put("method", toolInfo.getString("method"));
                                    toolCallEvent.put("service", toolInfo.getString("service"));
                                    toolCallEvent.put("module", toolInfo.getString("module"));
                                }
                                toolCallEvent.put("arguments", functionArgs);
                                emitter.send(SseEmitter.event()
                                        .id("tool_call_" + System.currentTimeMillis())
                                        .data(toolCallEvent.toJSONString(), org.springframework.http.MediaType.APPLICATION_JSON));

                                // 执行工具（带错误处理）
                                String toolDisplayName = toolInfo != null ? toolInfo.getString("description") : functionName;
                                if (toolDisplayName != null && toolDisplayName.length() > 20) {
                                    toolDisplayName = toolDisplayName.substring(0, 20) + "...";
                                }
                                sendStatusEvent(emitter, "executing_tool", "正在调用工具: " + toolDisplayName);
                                String toolResult;
                                try {
                                    toolResult = agentToolExecutor.execute(functionName, functionArgs, userInfo);
                                } catch (Exception toolEx) {
                                    String errorMsg = toolEx.getMessage();
                                    if (errorMsg != null && errorMsg.contains("权限")) {
                                        toolResult = "{\"success\":false,\"error\":\"权限不足：" + errorMsg + "。请联系管理员开通相应权限。\"}";
                                    } else {
                                        toolResult = "{\"success\":false,\"error\":\"工具执行失败：" + errorMsg + "\"}";
                                    }
                                    log.error("[Agent] 工具执行异常: {}", functionName, toolEx);
                                }
                                log.info("[Agent] 工具执行完成: {}, 结果长度: {}", functionName, toolResult != null ? toolResult.length() : 0);
                                sendStatusEvent(emitter, "tool_done", "工具调用完成");

                                // 发送工具结果事件
                                JSONObject toolResultEvent = new JSONObject();
                                toolResultEvent.put("type", "tool_result");
                                toolResultEvent.put("function_name", functionName);
                                if (toolInfo != null) {
                                    toolResultEvent.put("endpoint", toolInfo.getString("endpoint"));
                                }
                                toolResultEvent.put("result", toolResult);
                                emitter.send(SseEmitter.event()
                                        .id("tool_result_" + System.currentTimeMillis())
                                        .data(toolResultEvent.toJSONString(), org.springframework.http.MediaType.APPLICATION_JSON));

                                // 将工具结果添加到消息列表
                                JSONObject toolMessage = new JSONObject();
                                if (toolCallId != null) {
                                    // 原生function calling格式：使用tool角色
                                    toolMessage.put("role", "tool");
                                    toolMessage.put("tool_call_id", toolCallId);
                                    toolMessage.put("content", toolResult);
                                } else {
                                    // 文本解析格式：使用user角色模拟
                                    toolMessage.put("role", "user");
                                    toolMessage.put("content", "以下是工具 [" + functionName + "] 的返回结果，请根据此数据继续执行下一步或给出最终答案：\n" + toolResult);
                                }
                                messages.add(toolMessage);
                            }

                            // 增加工具调用轮次计数
                            toolCallRoundCount++;

                            // 添加工具结果汇总消息，帮助AI理解已完成的工作
                            JSONObject summaryMsg = new JSONObject();
                            summaryMsg.put("role", "system");
                            summaryMsg.put("content", "本轮已执行 " + parsedToolCalls.size() + " 个工具调用，结果已在上方。" +
                                    "累计已执行 " + toolCallRoundCount + " 轮工具调用。" +
                                    "请根据已获取的所有数据直接输出最终答案给用户，不要再调用工具。");
                            messages.add(summaryMsg);

                            // 继续循环，让AI处理工具结果
                            log.info("[Agent] 工具执行完毕，已执行{}轮工具调用，继续下一轮循环，当前消息数: {}", toolCallRoundCount, messages.size());
                            continue;

                        } else {
                            // 没有工具调用，检测是否为过渡性回复（如"请稍等，我将调用工具"）
                            boolean isIntermediate = isIntermediateResponse(aiContent);
                            if (isIntermediate && iteration < maxIterations - 2) {
                                // 过渡性回复：不输出给用户，强制AI继续处理
                                log.info("[Agent] 检测到过渡性回复，强制AI继续处理: {}", aiContent.substring(0, Math.min(aiContent.length(), 50)));
                                sendAgentDetailEvent(emitter, "ai_response",
                                    "第" + iteration + "轮: AI返回了过渡性回复，正在引导AI继续处理...");
                                // 添加用户消息，要求AI立即执行操作而非回复过渡性文字
                                JSONObject continueMsg = new JSONObject();
                                continueMsg.put("role", "user");
                                continueMsg.put("content", "不要回复过渡性文字。请立即执行工具调用或给出最终数据结果。如果需要调用工具，直接输出TOOL_CALL；如果数据已足够，直接用中文汇总数据回答。");
                                messages.add(continueMsg);
                                continue;
                            }
                            // 真正的最终答案
                            fullContent.append(aiContent);
                            JSONObject contentEvent = new JSONObject();
                            contentEvent.put("content", aiContent);
                            emitter.send(SseEmitter.event()
                                    .id(String.valueOf(System.currentTimeMillis()))
                                    .data(contentEvent.toJSONString(), org.springframework.http.MediaType.APPLICATION_JSON));
                            break;
                        }
                    } // end while

                    // 如果循环结束后仍未生成最终答案（如模型一直返回工具调用），尝试让AI给出最终答案
                    if (fullContent.length() == 0) {
                        log.warn("[Agent] 循环结束未生成最终答案，已执行{}轮工具调用，尝试最后一次强制回答", toolCallRoundCount);
                        // 最后一次尝试：强制AI给出最终答案（不带工具）
                        try {
                            JSONObject lastMsg = new JSONObject();
                            lastMsg.put("role", "user");
                            lastMsg.put("content", "请根据上面所有的工具返回结果，直接用中文汇总回答用户的问题。不要调用任何工具。");
                            messages.add(lastMsg);
                            JSONObject lastResponse = callAIWithoutTools(messages, dto.getModel());
                            String lastContent = lastResponse.getString("content");
                            if (StrUtil.isNotBlank(lastContent)) {
                                fullContent.append(lastContent);
                                JSONObject contentEvent = new JSONObject();
                                contentEvent.put("content", lastContent);
                                emitter.send(SseEmitter.event()
                                        .id(String.valueOf(System.currentTimeMillis()))
                                        .data(contentEvent.toJSONString(), org.springframework.http.MediaType.APPLICATION_JSON));
                            }
                        } catch (Exception lastEx) {
                            log.error("[Agent] 最后一次尝试也失败了", lastEx);
                        }
                        // 如果仍然没有内容，使用普通AI直接回答原始问题
                        if (fullContent.length() == 0) {
                            log.warn("[Agent] 工具调用后未生成回复，使用普通AI直接回答原始问题");
                            try {
                                // 构建原始问题消息（不带工具上下文）
                                List<JSONObject> simpleMessages = new ArrayList<>();
                                // 只保留用户的第一条消息
                                for (JSONObject msg : messages) {
                                    if ("user".equals(msg.getString("role"))) {
                                        simpleMessages.add(msg);
                                        break;
                                    }
                                }
                                if (!simpleMessages.isEmpty()) {
                                    JSONObject simpleResponse = callAIWithoutTools(simpleMessages, dto.getModel());
                                    String simpleContent = simpleResponse.getString("content");
                                    if (StrUtil.isNotBlank(simpleContent)) {
                                        fullContent.append(simpleContent);
                                        JSONObject contentEvent = new JSONObject();
                                        contentEvent.put("content", simpleContent);
                                        emitter.send(SseEmitter.event()
                                                .id(String.valueOf(System.currentTimeMillis()))
                                                .data(contentEvent.toJSONString(), org.springframework.http.MediaType.APPLICATION_JSON));
                                    }
                                }
                            } catch (Exception simpleEx) {
                                log.error("[Agent] 普通AI回答也失败", simpleEx);
                            }
                        }
                        // 如果仍然没有内容，显示错误信息
                        if (fullContent.length() == 0) {
                            String fallbackMsg = "AI在" + toolCallRoundCount + "轮工具调用后未能生成最终回复，请尝试重新提问或简化问题。";
                            fullContent.append(fallbackMsg);
                            JSONObject contentEvent = new JSONObject();
                            contentEvent.put("content", fallbackMsg);
                            emitter.send(SseEmitter.event()
                                    .id(String.valueOf(System.currentTimeMillis()))
                                    .data(contentEvent.toJSONString(), org.springframework.http.MediaType.APPLICATION_JSON));
                        }
                    }
                } // end else

                // 保存会话和消息
                DeepseekChatSessions session = null;
                if (StrUtil.isBlankOrUndefined(sessionId)) {
                    sessionId = UUID.randomUUID().toString();
                    for (DeepseekChatMessages message : newMessages) {
                        message.setSessionId(sessionId);
                    }
                    session = new DeepseekChatSessions();
                    session.setId(sessionId);
                    session.setUserid(userInfo.getId());
                    session.setOpttime(new Date());
                    session.setModel(dto.getModel());
                    session.setCreatetime(new Date());
                    session.setTitle(extractSessionTitle(dto.getMessages()));
                    this.iDeepseekChatSessionsService.save(session);
                } else {
                    session = iDeepseekChatSessionsService.getById(sessionId);
                }

                // 保存AI回复消息
                DeepseekChatMessages aiMessage = new DeepseekChatMessages();
                aiMessage.setSessionId(sessionId);
                aiMessage.setCreatetime(new Date());
                aiMessage.setContent(fullContent.toString());
                aiMessage.setRole("assistant");
                newMessages.add(aiMessage);
                iDeepseekChatMessagesService.saveBatch(newMessages);

                // 【P1】对话结束后异步执行学习分析
                final String finalSessionId = sessionId;
                final String userMsg = dto.getMessages() != null && !dto.getMessages().isEmpty()
                        ? dto.getMessages().get(dto.getMessages().size() - 1).getContent() : "";
                final String aiReply = fullContent.toString();
                executorService.execute(() -> {
                    try {
                        analyzeAndRecordLearning(userMsg, aiReply, finalSessionId, userInfo);
                    } catch (Exception ex) {
                        log.warn("学习分析失败（不影响正常使用）: {}", ex.getMessage());
                    }
                });

                // 发送完成事件
                JSONObject completeData = new JSONObject();
                completeData.put("id", sessionId);
                completeData.put("content", "[DONE]");
                log.info("[Agent] Agent流式完成, sessionId={}", sessionId);
                emitter.send(SseEmitter.event()
                        .id("complete")
                        .data(completeData.toJSONString(), org.springframework.http.MediaType.APPLICATION_JSON));

                emitter.complete();
                log.info("[Agent] SSE连接已关闭");

            } catch (Exception e) {
                log.error("[Agent] Agent流式请求失败", e);
                try {
                    JSONObject errorData = new JSONObject();
                    errorData.put("error", e.getMessage());
                    emitter.send(SseEmitter.event()
                            .data(errorData.toJSONString(), org.springframework.http.MediaType.APPLICATION_JSON));
                } catch (IOException ex) {
                    log.error("发送错误信息失败", ex);
                }
                emitter.completeWithError(e);
            } finally {
                // 清理Shiro上下文，防止内存泄漏
                ThreadContext.unbindSecurityManager();
                ThreadContext.unbindSubject();
            }
        });

        emitter.onTimeout(() -> {
            log.warn("Agent SSE连接超时");
            emitter.complete();
        });

        emitter.onError(e -> {
            log.error("Agent SSE连接错误", e);
        });

        return emitter;
    }

