public void handItem(Map<String, Object> item,Map<String,Map<String,Object>> planmap,PlanDetailDTO dto,
                         Map<String, Map<String, ProductInPresale>> presaleCache,
                         Map<String, Integer> feignCache,
                         Map<String, FBAShipCycle> cycleCache,
                         Map<String, AmzInventoryPlanning> planCache,
                         Map<String, List<Map<String, Object>>> recordCache,
                         Map<String, AmzInboundFbaCycle> cycleListCache) {
	    String psku=item.get("sku").toString();
	    String marketplaceid=item.get("marketplaceid").toString();
	    String amazonauthid =item.get("amazonauthid").toString();
	    String groupid=item.get("groupid").toString();
	    String msku=item.get("msku").toString();
	    String key=groupid+amazonauthid+marketplaceid+psku+msku;
	    Map<String, Object> plansku = planmap.get(key);
		if(plansku!=null&&plansku.get("subplannum")!=null&&Integer.parseInt(plansku.get("subplannum").toString())>=1){
			LambdaQueryWrapper<AmzProductSalesPlanShipItem> query=new LambdaQueryWrapper<AmzProductSalesPlanShipItem>();
			query.eq(AmzProductSalesPlanShipItem::getShopid, dto.getShopid());
			query.eq(AmzProductSalesPlanShipItem::getGroupid, item.get("groupid").toString());
			query.eq(AmzProductSalesPlanShipItem::getMarketplaceid,item.get("marketplaceid").toString());
			query.eq(AmzProductSalesPlanShipItem::getSku, 	item.get("sku").toString());
			query.eq(AmzProductSalesPlanShipItem::getAmazonauthid, item.get("amazonauthid").toString());
			query.eq(AmzProductSalesPlanShipItem::getWarehouseid, dto.getWarehouseid());
			List<AmzProductSalesPlanShipItem> subList = iAmzProductSalesPlanShipItemService.list(query);
			item.put("subList", subList);
		}
	    if(plansku!=null) {
	    	item.put("subnum",plansku.get("subnum"));
	    	item.put("aftersalesday",plansku.get("aftersalesday"));
	    	item.put("amount",plansku.get("amount"));
	    	item.put("reallyamount",plansku.get("amount"));
	    } else {
	    	item.put("subnum",0);
	    	item.put("aftersalesday",0);
	    	item.put("amount",item.get("amount"));
	    }
		// 使用缓存的备货周期数据
		AmzInboundFbaCycle myfbacycle = cycleListCache.get(marketplaceid);
		if (myfbacycle == null) {
			List<AmzInboundFbaCycle> cycleList = iAmzInboundFbaCycleService.getInboundFbaCycle(dto.getShopid(), marketplaceid);
			myfbacycle = iAmzInboundFbaCycleService.getDefaultInboundFbaCycle(cycleList);
			if(myfbacycle != null) {
				cycleListCache.put(marketplaceid, myfbacycle);
			}
		}
		item.put("defaultTranstype", myfbacycle.getTranstype());
		// 使用缓存的FBA发货周期数据
		FBAShipCycle cycle = cycleCache != null ? cycleCache.get(psku) : iFBAShipCycleService.getFbaShipCycle(groupid, marketplaceid, psku);
	    if(cycle!=null&&cycle.getTranstype()!=null) {
        	myfbacycle=iAmzInboundFbaCycleService.getTransInboundFbaCycle(iAmzInboundFbaCycleService.getInboundFbaCycle(dto.getShopid(), marketplaceid),cycle.getTranstype());
        }
	    if(dto.getPlantype().equals("ship")&&dto.getIseu()) {
	     Integer inbound = iShipInboundItemService.summaryShipmentSku(groupid, marketplaceid, psku);
	    	if(inbound!=null) {
	    		if(item.get("quantity")==null) {
	    			item.put("oldquantity",  0);
	    			item.put("localinbound",  inbound);
	    			item.put("fbainbound",  0);
	    			item.put("quantity", inbound);
	    			item.put("inbounddiff", inbound);
	    		}else {
	    			Integer quantity= Integer.parseInt(item.get("quantity").toString());
	    			Integer myqty=item.get("localquantity")!=null?Integer.parseInt(item.get("localquantity").toString()):0;
	    			item.put("oldquantity",  quantity);
	    			item.put("localinbound",  inbound);
	    			if(dto.getIseu()==true) {
	    				item.put("fbainbound",  0);
	    				item.put("quantity", quantity+inbound);
	    				item.put("inbounddiff",inbound);
	    				item.put("localquantity",quantity);
	    			}else {
	    				item.put("fbainbound",  quantity-myqty);
	    				item.put("quantity", inbound+myqty);
	    				item.put("inbounddiff", quantity-myqty-inbound);
	    			}
	    		}
	    	}
	    }
		Integer shipcycle=getShipCycle(cycle,myfbacycle);
		Integer mincycle=getMinShipCycle(cycle,myfbacycle);
		item.put("shipday", shipcycle);
		item.put("warehouseid", dto.getWarehouseid());
		item.put("mincycle", mincycle);
		myfbacycle.setMinCycle(mincycle);
		if(cycle!=null) {
			if(cycle.getStockingcycle()!=null) {
				myfbacycle.setStockingCycle(cycle.getStockingcycle());
			}
			if(cycle.getTranstype()!=null) {
				myfbacycle.setTranstype(cycle.getTranstype());
			}
		}
		Integer sysavgsales=item.get("sysavgsales") == null ? 0 : Integer.parseInt(item.get("sysavgsales").toString());
		Integer fbaquantity=item.get("quantity") == null ? 0 : Integer.parseInt(item.get("quantity").toString());
		fbaquantity=fbaquantity+(item.get("formqty")!=null?Integer.parseInt(item.get("formqty").toString()):0);
		Integer reallyamount=item.get("reallyamount") == null ? 0 : Integer.parseInt(item.get("reallyamount").toString());
		if(marketplaceid.equals("EU")) {
			int sumseven = item.get("sumseven") == null ? 0 : Integer.parseInt(item.get("sumseven").toString());// 七日销量
			int summonth = item.get("summonth") == null ? 0 : Integer.parseInt(item.get("summonth").toString());
			int sum15 = item.get("sum15") == null ? 0 : Integer.parseInt(item.get("sum15").toString());
			Date openDate = item.get("openDate") == null ? null : AmzDateUtils.getDate(item.get("openDate"));
			DaysalesFormula formula = daysalesFormulaService.selectByShopid(dto.getShopid());
			sysavgsales = DaysalesFormulaServiceImpl.getAvgSales(formula , summonth, sumseven, sum15, openDate);
		}
		 String country="EU";
		 if(!marketplaceid.equals("EU")) {
			 Marketplace market = marketplaceService.findMapByMarketplaceId().get(marketplaceid);
			 if(market!=null) {
				 country=market.getMarket();
			 }
			if(market!=null&&item.get("asin")!=null) {
				item.put("url", "https://www."+market.getPointName()+"/dp/"+item.get("asin").toString()+"?th=1&psc=1");
			}
		 }
		Integer overseaqty=0;
		if(feignCache!=null) {
			String feignKey = msku + "_" + country;
			Integer cachedOverseaqty = feignCache.get(feignKey);
			if(cachedOverseaqty!=null) {
				overseaqty = cachedOverseaqty;
			}
		} else {
			try {
				Result<Map<String, Object>> materialResult = erpClientOneFeign.getMSkuDeliveryAndInv(dto.getShopid(), groupid, msku, country,"false");
			    if(Result.isSuccess(materialResult)&&materialResult.getData()!=null) {
			    	if(materialResult.getData().get("overseaqty")!=null) {
			    		overseaqty=Integer.valueOf(materialResult.getData().get("overseaqty").toString());
			    	}
			    }
			}catch(FeignException e) {
				 e.printStackTrace();
			}
		}
		if(dto.getPlantype().equals("purchase")) {
			Integer needpurchase=item.get("needpurchase")==null?0:Integer.parseInt(item.get("needpurchase").toString());
			if(needpurchase>dto.getAmount()) {
				reallyamount=dto.getAmount();
				dto.setAmount(0);
			}else {
				reallyamount=needpurchase;
				dto.setAmount(dto.getAmount()-needpurchase);
			}
		}
		Map<String, ProductInPresale> prelist = new HashMap<>();
		// 跳过预估销量数据查询（默认展开/全部展开时优化性能）
		if(dto.getSkipPrelist() == null || !dto.getSkipPrelist()) {
			if(presaleCache!=null) {
				String presaleKey = groupid + "_" + psku + "_" + marketplaceid;
				prelist = presaleCache.get(presaleKey);
			} else {
				prelist = iProductInPresaleService.getPresale(psku,marketplaceid,groupid);
			}
			if(prelist==null) {
				prelist = new HashMap<>();
			}
			Calendar c=Calendar.getInstance();
			if(prelist.size()>0) {
				int j=0;
				for (int i = 1; i <= 180; i++) {
					ProductInPresale old = prelist.get(GeneralUtil.formatDate(c.getTime()));
					if (old == null) {
						ProductInPresale presale = new ProductInPresale();
						presale.setQuantity(sysavgsales);
						prelist.put(GeneralUtil.formatDate(c.getTime()), presale);
						j++;
					}
					if(j>=30) break;
					c.add(Calendar.DATE, 1);
				}
				item.put("prelist", prelist);
			}
			// 动态计算 salesday、aftersalesday、salesdayAvgsales（基于实时库存+预估销量）
			Map<String, Object> dynamicSales = this.getDynamicSalesData(prelist, sysavgsales, fbaquantity, overseaqty, reallyamount);
			item.putAll(dynamicSales);
		}

		if(dto.getPlantype().equals("purchase")) {
			int aftersalesday=item.get("aftersalesday")==null?0:Integer.parseInt(item.get("aftersalesday").toString());
			int salesday=item.get("salesday")==null?0:Integer.parseInt(item.get("salesday").toString());
			if(salesday>aftersalesday) {
				item.put("aftersalesday",salesday);
			}
		}else {
			int aftersalesday=item.get("aftersalesday")==null?0:Integer.parseInt(item.get("aftersalesday").toString());
			int salesday=item.get("salesday")==null?0:Integer.parseInt(item.get("salesday").toString());
			if(salesday>aftersalesday) {
				item.put("aftersalesday",salesday);
			}
		}
		item.put("overseaqty", overseaqty);
		item.put("sysavgsales", sysavgsales);
		item.put("cycle", myfbacycle);
		item.put("transtype", myfbacycle.getTranstype());
		if(cycle!=null&&cycle.getTranstype()!=null) {
			item.put("settranstype", cycle.getTranstype());
		}else {
			item.put("settranstype", "");
		}
		if(cycle!=null&&cycle.getStockingcycle()!=null) {
			item.put("setstockingcycles", cycle.getStockingcycle());
		}else {
			item.put("setstockingcycles", "");
		}
		item.put("statuscolor",GeneralUtil.getColorType(item.get("statuscolor")));
		if(!country.equals("EU")) {
			// 使用缓存的库存规划数据
			AmzInventoryPlanning plandata = null;
			if (planCache != null) {
				String planKey = amazonauthid + "_" + psku + "_" + country;
				plandata = planCache.get(planKey);
			} else {
				LambdaQueryWrapper<AmzInventoryPlanning> query=new LambdaQueryWrapper<AmzInventoryPlanning>();
				query.eq(AmzInventoryPlanning::getAmazonauthid,amazonauthid);
				query.eq(AmzInventoryPlanning::getSku,psku);
				query.and(wrapper -> {
					wrapper.eq(AmzInventoryPlanning::getCondition,"new")
					.or().eq(AmzInventoryPlanning::getCondition,"New")
							.or().eq(AmzInventoryPlanning::getCondition,"");
				});
				query.eq(AmzInventoryPlanning::getCountrycode,country);
				List<AmzInventoryPlanning> plandataList = iAmzInventoryPlanningService.list(query);
				for(AmzInventoryPlanning plandataItem:plandataList){
					if(plandata==null||"New".equals(plandataItem.getCondition())){
						plandata=plandataItem;
					}
				}
			}
			if(plandata!=null && dto.getPlantype().equals("ship")) {
				item.put("invplandata", plandata);
				item.put("fbainventorylevelhealthstatus", plandata.getFbaInventoryLevelHealthStatus());
				item.put("historicaldaysofsupply", plandata.getHistoricalDaysOfSupply());
			}

		}
		if(dto.getPlantype().equals("ship")) {
			// 使用缓存的发货记录数据（key为sku_marketplaceid）
			if (recordCache != null) {
				String recordKey = psku + "_" + marketplaceid;
				List<Map<String, Object>> shipRecords = recordCache.get(recordKey);
				if (shipRecords != null && !shipRecords.isEmpty()) {
					Map<String, Object> ship = shipRecords.get(0);
					SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
					String nowday = GeneralUtil.getStrDate(new Date());
					String shiprecord = GeneralUtil.formatDate(AmzDateUtils.getDate(ship.get("createdate").toString()), sdf);
					if (nowday.indexOf(shiprecord) >= 0) {
						shiprecord = "今日";
						item.put("dayship", "istoday");
					} else {
						item.put("dayship", "notoday");
					}
					item.put("shipRecordQuantity", ship.get("Quantity").toString());
					item.put("shipRecordStatusName",ship.get("statusName")!=null?ship.get("statusName").toString():"");
					item.put("shipRecordStatus", ship.get("status").toString());
					item.put("shipRecordDay", shiprecord);
					if (ship.get("arrivalTime") != null) {
						Calendar today = Calendar.getInstance();
						Calendar cal = today;
						cal.setTime(GeneralUtil.getDatez(ship.get("arrivalTime").toString()));
						cal.add(Calendar.DAY_OF_MONTH, myfbacycle.getPutOnDays());
						double arrivalday = GeneralUtil.distanceOfDay(cal, today);
						item.put("shipRecordArrivalday", arrivalday);
					}
				}
			} else {
				setShipRecord(item,dto.getShopid(),groupid,marketplaceid,psku,myfbacycle.getPutOnDays());
			}
		}
    }

synchronized  public String treatResponse(AmazonAuthority amazonAuthority, BufferedReader br)  {
		String log = "settlementId:";
		int lineNumber = 0;
		String line;
		String marketname = null;
		String currency = null;
		String settlementId = null;
		Date beginDate = null;
		Date endDate = null;
		Date postDate=null;
		Boolean invalid=false;
		Set<String> marketnameset = new HashSet<String>();
		AmzSettlementAccReport amzSettlementAccReport = new AmzSettlementAccReport();
		Map<String, Object> param = new HashMap<String, Object>();
		AmzSettlementReport report = null;
		List<AmzSettlementReport> settlist=new LinkedList<AmzSettlementReport>();
		int headerLine = 1;
		try {
			while ((line = br.readLine()) != null) {
				String[] info = line.split("\t");
				if (lineNumber >= 1&&info.length>0) {
					if ("settlement-id".equals(info[0])) {
						continue;
					}
					if (info.length == 1) {
						continue;
					}
					int index=0;
					report = new AmzSettlementReport();
					report.setAmazonAuthId(amazonAuthority.getId());
					report.setSettlementId(GeneralUtil.getIndexString(info, index));
					index=index+5;
					report.setCurrency(GeneralUtil.getIndexString(info, index));
					if (StrUtil.isNotEmpty(report.getCurrency())) {
						currency = report.getCurrency();
					} else {
						report.setCurrency(currency);
					}
					if (settlementId == null && report.getSettlementId() != null) {
						settlementId = report.getSettlementId();
						log += settlementId;
					}
					if (lineNumber == headerLine) {
						amzSettlementAccReport.setAmazonauthid(amazonAuthority.getId());
						amzSettlementAccReport.setSettlementId(GeneralUtil.getIndexString(info, 0));
						String startdate=GeneralUtil.getIndexString(info, 1);
						startdate=startdate.replace(" UTC", "");
						String enddate=GeneralUtil.getIndexString(info, 2);
						enddate=enddate.replace(" UTC", "");
						String depositdate=GeneralUtil.getIndexString(info, 3);
						depositdate=depositdate.replace(" UTC", "");
						amzSettlementAccReport.setSettlementStartDate(getLocalTime(currency,startdate));
						amzSettlementAccReport.setSettlementEndDate(getLocalTime(currency,enddate));
						amzSettlementAccReport.setDepositDate(getLocalTime(currency,depositdate));
						String currency2 = GeneralUtil.getIndexString(info, 5);
						amzSettlementAccReport.setCurrency(currency2);
						postDate=AmzDateUtils.getDate(amzSettlementAccReport.getSettlementStartDate());
						if ("EUR".equals(currency2)) {
							amzSettlementAccReport.setTotalAmount(GeneralUtil.getIndexEurBigDecimal(info, 4));
						} else {
							amzSettlementAccReport.setTotalAmount(GeneralUtil.getIndexBigDecimal(info, 4));
						}
						param.put("settlement_id", settlementId);
						param.put("amazonAuthId", amazonAuthority.getId());
						amzSettlementReportMapper.deleteBatch(param);
						lineNumber++;
						continue;
					}
					++index;
