public synchronized  String treatResponse(AmazonAuthority amazonAuthority, BufferedReader br)  {
		String mlog="";
		int lineNumber = 0;
		InventoryReport record = null;
		String line;
		boolean hasremote=false;
		try {
			while ((line = br.readLine()) != null) {
				String[] info = line.split("\t");
				int length = info.length;
				if(lineNumber==0) {
					if(line.contains("afn-fulfillable-quantity-remote")) {
						hasremote=true;
					}
				}
				if (lineNumber != 0) {
					record = new InventoryReport();
					int i = 0;
					String sku = i < length ? info[i++] : null;
					if(sku!=null && sku.length()>50){
						sku = sku.substring(0, 50);
					}
					String fnsku = i < length ? info[i++] : null;
					String asin = i < length ? info[i++] : null;
					@SuppressWarnings("unused")
					String product_name = i < length ? info[i++] : null;
					String condition = i < length ? info[i++] : null;
					String your_price = i < length ? info[i++] : null;
					String mfn_listing_exists = i < length ? info[i++] : null;
					String mfn_fulfillable_quantity = i < length ? info[i++] : null;
					String afn_listing_exists = i < length ? info[i++] : null;
					String afn_warehouse_quantity = i < length ? info[i++] : null;
					String afn_fulfillable_quantity = i < length ? info[i++] : null;
					String afn_unsellable_quantity = i < length ? info[i++] : null;
					String afn_reserved_quantity = i < length ? info[i++] : null;
					String afn_total_quantity = i < length ? info[i++] : null;
					String per_unit_volume = i < length ? info[i++] : null;
					String afn_inbound_working_quantity = i < length ? info[i++] : null;
					String afn_inbound_shipped_quantity = i < length ? info[i++] : null;
					String afn_inbound_receiving_quantity = i < length ? info[i++] : null;
					String afn_researching_quantity = i < length ? info[i++] : null;
					String afn_reserved_future_supply = i < length ? info[i++] : null;
					String afn_future_supply_buyable = i < length ? info[i++] : null;
					String afn_fulfillable_quantity_remote=hasremote && i < length ? info[i++] : null;
					if(StrUtil.isNotBlank(afn_fulfillable_quantity_remote)) {
						//log.info(afn_fulfillable_quantity_remote);
					}
					record.setAsin(asin);
					record.setSku(sku);
					record.setFnsku(fnsku);
					if(condition.length()>19)condition.substring(0, 18);
					record.setPcondition(condition);
					if(StrUtil.isEmpty(your_price)||"Unknown".equals(your_price)) {
						if((StrUtil.isEmpty(condition)||"Unknown".equals(condition))&&(afn_total_quantity==null)) {
							lineNumber++;
							continue;
						}
					}

					if(condition.contains("No Listing")) {
						lineNumber++;
					    continue;
					}
					record.setYourPrice(GeneralUtil.getBigDecimal(your_price));
					record.setMfnListingExists(mfn_listing_exists);
					record.setMfnFulfillableQuantity(GeneralUtil.getInteger(mfn_fulfillable_quantity));
					record.setAfnListingExists(afn_listing_exists);
					record.setAfnWarehouseQuantity(GeneralUtil.getInteger(afn_warehouse_quantity));
					record.setAfnFulfillableQuantity(GeneralUtil.getInteger(afn_fulfillable_quantity));
					record.setAfnUnsellableQuantity(GeneralUtil.getInteger(afn_unsellable_quantity));
					record.setAfnReservedQuantity(GeneralUtil.getInteger(afn_reserved_quantity));
					record.setAfnTotalQuantity(GeneralUtil.getInteger(afn_total_quantity));
					record.setPerUnitVolume(GeneralUtil.getBigDecimal(per_unit_volume));
					record.setAfnInboundWorkingQuantity(GeneralUtil.getInteger(afn_inbound_working_quantity));
					record.setAfnInboundShippedQuantity(GeneralUtil.getInteger(afn_inbound_shipped_quantity));
					record.setAfnInboundReceivingQuantity(GeneralUtil.getInteger(afn_inbound_receiving_quantity));
					record.setAfnResearchingQuantity(GeneralUtil.getInteger(afn_researching_quantity));
					record.setAfnReservedFutureSupply(GeneralUtil.getInteger(afn_reserved_future_supply));
					record.setAfnFutureSupplyBuyable(GeneralUtil.getInteger(afn_future_supply_buyable));
					record.setAmazonAuthId(amazonAuthority.getId());
					if ("EU".equals(amazonAuthority.getMarketPlace().getRegion())) {
						record.setMarketplaceid(amazonAuthority.getMarketPlace().getRegion());
					} else {
						record.setMarketplaceid(amazonAuthority.getMarketPlace().getMarketplaceid());
					}
					record.setByday(amazonAuthority.getCaptureDateTime());
					try {
						record.setIsnewest(true);
						QueryWrapper<InventoryReport> query=new QueryWrapper<InventoryReport>();
						query.eq("sku", record.getSku());
						query.eq("marketplaceid", record.getMarketplaceid());
						query.eq("amazonAuthId", record.getAmazonAuthId());
						InventoryReport oldone = inventoryReportMapper.selectOne(query);
						if(GeneralUtil.distanceOfDay(oldone.getByday(),new Date())>5){
							if(oldone!=null) {
								inventoryReportMapper.update(record, query);
							}else {
								inventoryReportMapper.insert(record);
							}
						}
						inventoryReportMapper.newestInsert(record);
					}catch(Exception e) {
						e.printStackTrace();
					}
				}
				lineNumber++;
			}
		} catch (IOException e) {
			// TODO Auto-generated catch block
			log.info("ReportAmzInventoryService:"+e.getMessage());
			e.printStackTrace();
		}  finally {
				if(br!=null) {
				try {
					br.close();
				} catch (IOException e) {
					// TODO Auto-generated catch block
					e.printStackTrace();
				}
				}
	}
      return mlog;
	}

@Override
    public int importSubjects(InputStream inputStream, String groupId, String importType) throws IOException {
        ExcelUtil<FinAccountingSubjects> util = new ExcelUtil<FinAccountingSubjects>(FinAccountingSubjects.class);
        List<FinAccountingSubjects> list = util.importExcel(inputStream);
        int count = 0;
        // 收集Excel中所有科目编码，用于覆盖导入时禁用不在Excel中的科目
        List<String> excelSubjectCodes = new ArrayList<>();

        for (FinAccountingSubjects subject : list) {
            // 检查科目是否已存在
            subject.setGroupid(groupId);

            // 转换类别：中文名称 -> 数字代码
            if (subject.getSubjectTypeName() != null) {
                switch (subject.getSubjectTypeName().trim()) {
                    // 子类别
                    case "流动资产":
                        subject.setSubjectType(6);
                        break;
                    case "非流动资产":
                        subject.setSubjectType(7);
                        break;
                    case "流动负债":
                        subject.setSubjectType(8);
                        break;
                    case "非流动负债":
                        subject.setSubjectType(9);
                        break;
                    case "所有者权益":
                        subject.setSubjectType(10);
                        break;
                    case "成本":
                        subject.setSubjectType(11);
                        break;
                    case "营业收入":
                        subject.setSubjectType(12);
                        break;
                    case "其他收益":
                        subject.setSubjectType(13);
                        break;
                    case "期间费用":
                        subject.setSubjectType(14);
                        break;
                    case "其他损失":
                        subject.setSubjectType(15);
                        break;
                    case "营业成本及税金":
                        subject.setSubjectType(16);
                        break;
                    case "以前年度损益调整":
                        subject.setSubjectType(17);
                        break;
                    case "所得税":
                        subject.setSubjectType(18);
                        break;
                }
            }

            // 转换余额方向：中文名称 -> 数字代码
            if (subject.getDirectionName() != null) {
                switch (subject.getDirectionName().trim()) {
                    case "借":
                        subject.setDirection(1);
                        break;
                    case "贷":
                        subject.setDirection(2);
                        break;
                }
            }else {
                subject.setDirection(2);
            }
            // 转换状态：中文名称 -> 数字代码
            if (subject.getStatusName() != null) {
                switch (subject.getStatusName().trim()) {
                    case "启用":
                        subject.setStatus(1);
                        break;
                    case "停用":
                        subject.setStatus(0);
                        break;
                }
            }else {
                subject.setStatus(1);
            }

            //是否调汇
            if (subject.getExchangeName() != null) {
                switch (subject.getExchangeName().trim()) {
                    case "是":
                        subject.setIsExchange(true);
                        break;
                    case "否":
                        subject.setIsExchange(false);
                        break;
                }
            }else {
                subject.setIsExchange(false);
            }

            // 转换是否现金科目：中文名称 -> 数字代码
            if (subject.getIsCashName() != null) {
                switch (subject.getIsCashName().trim()) {
                    case "是":
                        subject.setCash(true);
                        break;
                    case "否":
                        subject.setCash(false);
                        break;
                }
            }else {
                subject.setCash(false);
            }

            // 转换是否平行科目：中文名称 -> 数字代码
            if (subject.getIsParallelName() != null) {
                switch (subject.getIsParallelName().trim()) {
                    case "是":
                        subject.setIsParallel(true);
                        break;
                    case "否":
                        subject.setIsParallel(false);
                        break;
                }
            }else {
                subject.setIsParallel(false);
            }

            // 根据 subjectCode 计算 subjectLevel 和 parentCode
            if (subject.getSubjectCode() != null) {
                // 移除所有空格，确保编码格式正确
                String subjectCode = subject.getSubjectCode().trim().replaceAll("\\s+", "");
                subject.setSubjectCode(subjectCode);
                int codeLength = subjectCode.length();

                // 计算 subjectLevel
                int subjectLevel = 0;
                if (codeLength == 4) {
                    subjectLevel = 1;
                } else if (codeLength == 6) {
                    subjectLevel = 2;
                } else if (codeLength == 8) {
                    subjectLevel = 3;
                } else if (codeLength == 10) {
                    subjectLevel = 4;
                }
                subject.setSubjectLevel(subjectLevel);

                // 计算 parentCode
                if (subjectLevel > 1) {
                    // parentCode 是当前 code 减去最后2位字符
                    String parentCode = subjectCode.substring(0, codeLength - 2);
                    subject.setParentCode(parentCode);
                } else {
                    // 一级科目没有父级
                    subject.setParentCode("0");
                }

                // 收集科目编码
                excelSubjectCodes.add(subjectCode);
            }
            subject.setUpdatedTime(new Date());
            // 状态以Excel中"状态"列的值为准，"启用"=1，"停用"=0

            if ("override".equals(importType)) {
                // 覆盖导入：不限状态查询，找到已存在的记录（包括已停用的）
                FinAccountingSubjects existing = finAccountingSubjectsMapper.selectByGroupCodeAnyStatus(subject.getGroupid(), subject.getSubjectCode());
                if (existing == null) {
                    // 新增科目
                    subject.setCreatedTime(new Date());
                    count += finAccountingSubjectsMapper.insertFinAccountingSubjects(subject);
                } else {
                    // 更新科目
                    subject.setSubjectId(existing.getSubjectId());
                    count += finAccountingSubjectsMapper.updateFinAccountingSubjects(subject);
                }
            } else {
                // 增量导入：只查询启用状态的记录
                FinAccountingSubjects existing = finAccountingSubjectsMapper.selectByTenantIdAndSubjectCode(subject.getGroupid(), subject.getSubjectCode());
                if (existing == null) {
                    // 新增科目
                    subject.setCreatedTime(new Date());
                    count += finAccountingSubjectsMapper.insertFinAccountingSubjects(subject);
                } else {
                    // 更新科目
                    subject.setSubjectId(existing.getSubjectId());
                    count += finAccountingSubjectsMapper.updateFinAccountingSubjects(subject);
                }
            }
        }

        // 覆盖导入：将不在Excel中的启用科目设为停用
        if ("override".equals(importType)) {
            finAccountingSubjectsMapper.batchDisableSubjects(groupId, excelSubjectCodes);
        }

        return count;
    }

@Override
    public List<Map<String, Object>> selectTopLevelSummaryFull(FinLedgerDTO dto) {
        // 1. 查询基础数据
        List<Map<String, Object>> rawData = this.finGeneralLedgerMapper.selectTopLevelSummary(dto);

        // 2. 按科目分组
        Map<String, List<Map<String, Object>>> subjectMap = new LinkedHashMap<>();
        if (rawData != null && !rawData.isEmpty()) {
            for (Map<String, Object> item : rawData) {
                String subjectCode = item.get("subjectCode").toString();
                subjectMap.computeIfAbsent(subjectCode, k -> new ArrayList<>()).add(item);
            }
        }

        // 3. 查询从年初到当前期间有余额的科目，补充缺失的科目
        String yearStart = dto.getStartPeriod().substring(0, 4) + "01";
        List<Map<String, Object>> yearData = this.finGeneralLedgerMapper.selectTopLevelSummaryByDateRange(
            dto.getGroupid(), yearStart, dto.getStartPeriod());
        if (yearData != null) {
            for (Map<String, Object> item : yearData) {
                String subjectCode = item.get("subjectCode").toString();
                // 如果该科目在当前查询结果中不存在，则添加
                if (!subjectMap.containsKey(subjectCode)) {
                    // 检查是否有余额
                    BigDecimal endBalance = item.get("endBalance") != null ? 
                        new BigDecimal(item.get("endBalance").toString()) : BigDecimal.ZERO;
                    Integer endDirection = item.get("endDirection") != null ? 
                        Integer.parseInt(item.get("endDirection").toString()) : 1;

                    if (endBalance.compareTo(BigDecimal.ZERO) != 0) {
                        subjectMap.computeIfAbsent(subjectCode, k -> new ArrayList<>()).add(item);
                    }
                }
            }
        }

        if (subjectMap.isEmpty()) {
            return new ArrayList<>();
        }

        // 4. 查询年初到查询起始期间之前期间的数据，用于预累加本年累计借方/贷方
        String startYear = dto.getStartPeriod().substring(0, 4);
        String yearStartPeriod = startYear + "01";
        String prevStartPeriod = getPrevPeriod(dto.getStartPeriod());
        Map<String, BigDecimal[]> yearPreDebitCreditMap = new LinkedHashMap<>();
        if (yearStartPeriod.compareTo(prevStartPeriod) <= 0) {
            List<Map<String, Object>> yearPreData = this.finGeneralLedgerMapper.selectTopLevelSummaryByDateRange(
                dto.getGroupid(), yearStartPeriod, prevStartPeriod);
            if (yearPreData != null) {
                for (Map<String, Object> item : yearPreData) {
                    String sc = item.get("subjectCode").toString();
                    BigDecimal debit = item.get("debitTotal") != null ? new BigDecimal(item.get("debitTotal").toString()) : BigDecimal.ZERO;
                    BigDecimal credit = item.get("creditTotal") != null ? new BigDecimal(item.get("creditTotal").toString()) : BigDecimal.ZERO;
                    BigDecimal[] existing = yearPreDebitCreditMap.get(sc);
                    if (existing != null) {
                        existing[0] = existing[0].add(debit);
                        existing[1] = existing[1].add(credit);
                    } else {
                        yearPreDebitCreditMap.put(sc, new BigDecimal[]{debit, credit});
                    }
                }
            }
        }

        // 4.1 查询上个月的期末余额作为期初余额（解决单独查询某月时期初余额为0的问题）
        Map<String, BigDecimal[]> prevMonthEndBalanceMap = new LinkedHashMap<>();
        String prevMonth = getPrevPeriod(dto.getStartPeriod());
        List<Map<String, Object>> prevMonthData = this.finGeneralLedgerMapper.selectTopLevelSummaryByDateRange(
            dto.getGroupid(), prevMonth, prevMonth);
        if (prevMonthData != null) {
            for (Map<String, Object> item : prevMonthData) {
                String sc = item.get("subjectCode").toString();
                BigDecimal endBalance = item.get("endBalance") != null ? new BigDecimal(item.get("endBalance").toString()) : BigDecimal.ZERO;
                Integer endDirection = item.get("endDirection") != null ? Integer.parseInt(item.get("endDirection").toString()) : 1;
                prevMonthEndBalanceMap.put(sc, new BigDecimal[]{endBalance, new BigDecimal(endDirection)});
            }
        }

        // 5. 生成完整的期间列表
        List<String> allPeriods = generatePeriodRange(dto.getStartPeriod(), dto.getEndPeriod());

        // 6. 构建完整的总账数据
        List<Map<String, Object>> result = new ArrayList<>();

        for (Map.Entry<String, List<Map<String, Object>>> entry : subjectMap.entrySet()) {
            String subjectCode = entry.getKey();
            List<Map<String, Object>> periodList = entry.getValue();

            // 按期间排序
            periodList.sort((a, b) -> a.get("period").toString().compareTo(b.get("period").toString()));

            // 获取科目信息
            String subjectName = periodList.get(0).get("subjectName") != null ? 
                periodList.get(0).get("subjectName").toString() : "";

            // 将凭证数据按期间建立索引
            Map<String, Map<String, Object>> periodDataMap = new LinkedHashMap<>();
            for (Map<String, Object> periodData : periodList) {
                periodDataMap.put(periodData.get("period").toString(), periodData);
            }

            // 本年累计变量（每年重新计算）
            BigDecimal yearCumulativeDebit = BigDecimal.ZERO;
            BigDecimal yearCumulativeCredit = BigDecimal.ZERO;
            String currentYear = "";

            // 上期期末余额（用于填补缺失期间）
            BigDecimal lastEndBalance = BigDecimal.ZERO;
            Integer lastEndDirection = 1;

            // 初始化期初余额：使用上个月的期末余额（2月的期初 = 1月的期末）
            BigDecimal[] prevMonthBalance = prevMonthEndBalanceMap.get(subjectCode);
            if (prevMonthBalance != null) {
                lastEndBalance = prevMonthBalance[0];
                lastEndDirection = prevMonthBalance[1].intValue();
            }

            // 遍历所有期间
            for (String period : allPeriods) {
                String periodYear = period.substring(0, 4);

                // 如果是新的一年，重置本年累计（并预累加年初到查询起始期间之前的借方/贷方）
                if (!periodYear.equals(currentYear)) {
                    currentYear = periodYear;
                    if (currentYear.equals(startYear)) {
                        BigDecimal[] preDC = yearPreDebitCreditMap.get(subjectCode);
                        yearCumulativeDebit = preDC != null ? preDC[0] : BigDecimal.ZERO;
                        yearCumulativeCredit = preDC != null ? preDC[1] : BigDecimal.ZERO;
                    } else {
                        yearCumulativeDebit = BigDecimal.ZERO;
                        yearCumulativeCredit = BigDecimal.ZERO;
                    }
                }

                // 获取该期间的数据，如果没有则使用上期期末余额
                Map<String, Object> periodData = periodDataMap.get(period);

                BigDecimal beginBalance;
                Integer beginDirection;
                BigDecimal periodDebit;
                BigDecimal periodCredit;
                BigDecimal periodEndBalance;
                Integer periodDirection;

                if (periodData != null) {
                    // 有数据，使用表中的借贷发生额
                    // 期初余额使用上期结转的期末余额
                    beginBalance = lastEndBalance;
                    beginDirection = lastEndDirection;
                    periodDebit = periodData.get("debitTotal") != null ? 
                        new BigDecimal(periodData.get("debitTotal").toString()) : BigDecimal.ZERO;
                    periodCredit = periodData.get("creditTotal") != null ? 
                        new BigDecimal(periodData.get("creditTotal").toString()) : BigDecimal.ZERO;

                    // 增量计算期末余额：上期期末余额 + 本期借方 - 本期贷方
                    // lastEndBalance 是带符号的值（正=借，负=贷）
                    BigDecimal signedNewBalance = lastEndBalance.add(periodDebit).subtract(periodCredit);
                    if (signedNewBalance.compareTo(BigDecimal.ZERO) > 0) {
                        periodDirection = 1;
                        periodEndBalance = signedNewBalance;
                    } else if (signedNewBalance.compareTo(BigDecimal.ZERO) < 0) {
                        periodDirection = 2;
                        periodEndBalance = signedNewBalance;
                    } else {
                        periodDirection = 0;
                        periodEndBalance = BigDecimal.ZERO;
                    }

                    // 更新上期期末余额
                    lastEndBalance = periodEndBalance;
                    lastEndDirection = periodDirection;
                } else {
                    // 没有数据，使用上期期末余额作为期初和期末
                    beginBalance = lastEndBalance;
                    beginDirection = lastEndDirection;
                    periodDebit = BigDecimal.ZERO;
                    periodCredit = BigDecimal.ZERO;
                    periodEndBalance = lastEndBalance;
                    periodDirection = lastEndDirection;
                }

                // 如果期初余额为0，方向为平
                if (beginBalance.compareTo(BigDecimal.ZERO) == 0) {
                    beginDirection = 0;
                }

                // 根据方向处理余额：确保余额显示为正数
                BigDecimal displayBeginBalance = beginBalance;
                if (beginDirection == 2) {
                    // 贷方余额，显示为正数
                    displayBeginBalance = beginBalance.abs();
                }

                // 期初余额只在第一个期间显示
                if (allPeriods.indexOf(period) == 0) {
                    Map<String, Object> beginRow = new LinkedHashMap<>();
                    beginRow.put("subjectCode", subjectCode);
                    beginRow.put("subjectName", subjectName);
                    beginRow.put("period", period);
                    beginRow.put("summary", "期初余额");
                    beginRow.put("debitTotal", null);
                    beginRow.put("creditTotal", null);
                    beginRow.put("direction", beginDirection);
                    beginRow.put("balance", displayBeginBalance);
                    beginRow.put("rowType", "begin");
                    result.add(beginRow);
                }

                // 累加本年累计
                yearCumulativeDebit = yearCumulativeDebit.add(periodDebit);
                yearCumulativeCredit = yearCumulativeCredit.add(periodCredit);

                // 如果期末余额为0，方向为平
                if (periodEndBalance.compareTo(BigDecimal.ZERO) == 0) {
                    periodDirection = 0;
                }

                // 根据方向处理余额：确保余额显示为正数
                BigDecimal displayEndBalance = periodEndBalance;
                if (periodDirection == 2) {
                    // 贷方余额，显示为正数
                    displayEndBalance = periodEndBalance.abs();
                }

                // 本期合计行
                Map<String, Object> periodRow = new LinkedHashMap<>();
                periodRow.put("subjectCode", subjectCode);
                periodRow.put("subjectName", subjectName);
                periodRow.put("period", period);
                periodRow.put("summary", "本期合计");
                periodRow.put("debitTotal", periodDebit);
                periodRow.put("creditTotal", periodCredit);
                periodRow.put("direction", periodDirection);
                periodRow.put("balance", displayEndBalance);
                periodRow.put("rowType", "period");
                result.add(periodRow);

                // 本年累计行
                // 本年累计余额 = 当期期末余额（从年初到当前期间的累计余额）
                Map<String, Object> yearRow = new LinkedHashMap<>();
                yearRow.put("subjectCode", subjectCode);
                yearRow.put("subjectName", subjectName);
                yearRow.put("period", period);
                yearRow.put("summary", "本年累计");
                yearRow.put("debitTotal", yearCumulativeDebit);
                yearRow.put("creditTotal", yearCumulativeCredit);
                yearRow.put("direction", periodDirection);
                yearRow.put("balance", displayEndBalance);
                yearRow.put("rowType", "year");
                result.add(yearRow);
            }
        }

        return result;
    }

public List<Map<String, Object>> findMaterialSizeByCondition(Map<String, Object> param){
