				continue;
			}
			if ("etself".equals(param.get("sizetype")) && (selfFBA == null || Float.parseFloat(selfFBA) != amzFBA.floatValue())) {
				j++;// remove次数
				result.remove(i - j + 1);
				continue;
			}
			if ("gtself".equals(param.get("sizetype")) && (selfFBA == null || Float.parseFloat(selfFBA) >= amzFBA.floatValue())) {
				j++;// remove次数
				result.remove(i - j + 1);
				continue;
			}
			if ("true".equals(param.get("isgtself")) && (selfFBA == null || Float.parseFloat(selfFBA) >= amzFBA.floatValue())) {
				j++;// remove次数
				result.remove(i - j + 1);
				continue;
			}
		}
		return result;
	}

@Override
    @Transactional
    public String importInvoicesFromJson(Map<String, List<Map<String, Object>>> sheets, String groupid, String userName)
    {
        if (sheets == null || sheets.isEmpty()) {
            log.warn("导入发票：数据为空");
            return "发票数据为空";
        }

        Date now = new Date();
        List<FinInvoice> allInvoices = new ArrayList<>();
        // 按页签名保留原始行数据，用于后续插入明细/扩展
        Map<String, List<Map<String, Object>>> sheetRowsMap = new HashMap<>();

        // 收集所有页签的发票主表数据
        for (Map.Entry<String, List<Map<String, Object>>> entry : sheets.entrySet()) {
            String sheetName = entry.getKey();
            List<Map<String, Object>> rows = entry.getValue();
            if (rows == null || rows.isEmpty()) continue;

            log.info("处理页签[{}]，共{}行", sheetName, rows.size());
            List<Map<String, Object>> validRows = new ArrayList<>();

            for (Map<String, Object> item : rows) {
                FinInvoice invoice = buildInvoiceFromRow(item, groupid, userName, now, sheetName);
                if (invoice.getDigitalInvoiceNo() == null && invoice.getInvoiceNo() == null) {
                    log.warn("页签[{}]中旡法确定发票唯一标识的行，跳过：{}", sheetName, item);
                    continue;
                }
                allInvoices.add(invoice);
                validRows.add(item);
            }
            if (!validRows.isEmpty()) {
                sheetRowsMap.put(sheetName, validRows);
            }
        }

        if (allInvoices.isEmpty()) {
            log.warn("导入发票：解析后数据为空");
            return "解析后发票数据为空";
        }

        // 1. 批量插入/更新主表
        log.info("准备插入主表，共{}条发票", allInvoices.size());
        int mainCount = finInvoiceLedgerMapper.batchInsertFinInvoice(allInvoices);
        log.info("主表影响{}行", mainCount);

        // 2. 查询所有涉及的发票号码→ID映射（同时支持数电发票号码和普通发票号码）
        Set<String> allInvoiceNos = new LinkedHashSet<>();
        for (FinInvoice inv : allInvoices) {
            if (inv.getDigitalInvoiceNo() != null) {
                allInvoiceNos.add(inv.getDigitalInvoiceNo());
            }
            if (inv.getInvoiceNo() != null) {
                allInvoiceNos.add(inv.getInvoiceNo());
            }
        }
        // 发票号码→ID映射（包含数电发票号码和普通发票号码）
        Map<String, Long> invoiceNoToIdMap = new HashMap<>();
        if (!allInvoiceNos.isEmpty()) {
            List<String> noList = new ArrayList<>(allInvoiceNos);
            // 分批查询，每批500
            for (int i = 0; i < noList.size(); i += 500) {
                List<String> batch = noList.subList(i, Math.min(i + 500, noList.size()));
                // 同时查询数电发票号码和普通发票号码
                List<FinInvoice> found = finInvoiceLedgerMapper.selectByDigitalInvoiceNos(batch);
                for (FinInvoice fi : found) {
                    if (fi.getDigitalInvoiceNo() != null) {
                        invoiceNoToIdMap.put(fi.getDigitalInvoiceNo(), fi.getId());
                    }
                    if (fi.getInvoiceNo() != null) {
                        invoiceNoToIdMap.put(fi.getInvoiceNo(), fi.getId());
                    }
                }
            }
        }
        log.info("发票号码→ID映射：{}条", invoiceNoToIdMap.size());

        // 3. 处理明细行（"信息汇总表"页签包含货物明细信息）
        int detailCount = 0;
        List<Map<String, Object>> summaryRows = sheetRowsMap.get("信息汇总表");
        if (summaryRows != null && !summaryRows.isEmpty()) {
            List<FinInvoiceDetail> details = new ArrayList<>();
            Set<Long> invoiceIdsToDelete = new LinkedHashSet<>();
            // 按发票号码分组，为同一发票的多行明细分配行号
            Map<String, Integer> lineNoMap = new HashMap<>();
            for (Map<String, Object> row : summaryRows) {
                // 尝试多种发票号码列名（信息汇总表可能使用不同的列名）
                String digitalNo = getStringValue(row, "数电发票号码", "全电发票号码", "数电票号码",
                        "发票号码", "发票号", "号码", "invoiceNo", "InvoiceNo", "invoice_no",
                        "发票代码号码", "电子客票号", "票号");
                if (digitalNo == null || digitalNo.isEmpty()) {
                    log.warn("信息汇总表中无法识别发票号码的行，跳过：{}", row);
                    continue;
                }
                Long invoiceId = invoiceNoToIdMap.get(digitalNo);
                if (invoiceId == null) {
                    log.warn("信息汇总表中发票号码[{}]未找到对应的主表记录，跳过", digitalNo);
                    continue;
                }

                // 只有当行包含明细字段时才插入明细表
                String goodsName = getStringValue(row, "货物或应税劳务名称", "货物名称", "商品名称", "项目名称");
                BigDecimal amount = getBigDecimalValue(row, "金额", "amountWithoutTax");
                if (goodsName == null && amount == null) {
                    log.warn("信息汇总表中发票号码[{}]的行缺少货物名称或金额，跳过", digitalNo);
                    continue;
                }

                invoiceIdsToDelete.add(invoiceId);
                int lineNo = lineNoMap.merge(digitalNo, 1, Integer::sum);
                FinInvoiceDetail detail = new FinInvoiceDetail();
                detail.setInvoiceId(invoiceId);
                detail.setLineNo(lineNo);
                detail.setGoodsName(goodsName);
                detail.setSpecModel(getStringValue(row, "规格型号", "规格"));
                detail.setUnit(getStringValue(row, "单位"));
                detail.setQuantity(getBigDecimalValue(row, "数量"));
                detail.setUnitPrice(getBigDecimalValue(row, "单价", "不含税单价"));
                detail.setAmountWithoutTax(amount);
                detail.setTaxRate(parseTaxRate(getStringValue(row, "税率")));
                detail.setTaxAmount(getBigDecimalValue(row, "税额", "taxAmount"));
                detail.setAmountWithTax(getBigDecimalValue(row, "价税合计", "含税金额"));
                detail.setTaxCategoryCode(getStringValue(row, "税收分类编码", "税收分类"));
                details.add(detail);
            }
            if (!details.isEmpty()) {
                // 先删除这些发票的旧明细记录，避免重复导入
                if (!invoiceIdsToDelete.isEmpty()) {
                    List<Long> idList = new ArrayList<>(invoiceIdsToDelete);
                    for (int i = 0; i < idList.size(); i += 500) {
                        List<Long> batch = idList.subList(i, Math.min(i + 500, idList.size()));
                        for (Long id : batch) {
                            finInvoiceDetailMapper.deleteByInvoiceId(id);
                        }
                    }
                    log.info("清理旧明细记录，涉及{}张发票", idList.size());
                }
                // 分批插入，每批200条
                for (int i = 0; i < details.size(); i += 200) {
                    detailCount += finInvoiceDetailMapper.batchInsert(details.subList(i, Math.min(i + 200, details.size())));
                }
                log.info("插入明细行{}条", detailCount);
            }
        }

        // 4. 处理扩展信息（货物运输服务、铁路电子客票等特定业务字段）
        int extCount = 0;
        // 货物运输服务扩展字段（支持多种页签名）
        extCount += processTransportExtension(sheetRowsMap.get("货物运输服务"), invoiceNoToIdMap, "TRANSPORT");
        extCount += processTransportExtension(sheetRowsMap.get("货物运输"), invoiceNoToIdMap, "TRANSPORT");
        extCount += processTransportExtension(sheetRowsMap.get("运输服务"), invoiceNoToIdMap, "TRANSPORT");
        // 铁路电子客票扩展字段（支持多种页签名）
        extCount += processTransportExtension(sheetRowsMap.get("铁路电子客票"), invoiceNoToIdMap, "RAILWAY");
        extCount += processTransportExtension(sheetRowsMap.get("铁路客票"), invoiceNoToIdMap, "RAILWAY");
        extCount += processTransportExtension(sheetRowsMap.get("电子客票"), invoiceNoToIdMap, "RAILWAY");
        // 其他可能的特定业务类型页签可以继续扩展...
        log.info("扩展信息处理完成，共{}条", extCount);

        // 构建导入结果描述
        StringBuilder msg = new StringBuilder();
        msg.append("导入完成：主表").append(allInvoices.size()).append("条");
        if (detailCount > 0) msg.append("，明细").append(detailCount).append("条");
        if (extCount > 0) msg.append("，扩展").append(extCount).append("条");
        log.info(msg.toString());
        // 导入后自动匹配supplier_id和carrier_id
        if (!allInvoices.isEmpty()) {
            log.info("========== 准备匹配供应商supplier_id ==========");
            matchAndSetSupplierId(groupid);
            log.info("========== 准备匹配承运商carrier_id ==========");
            matchAndSetCarrierId(groupid);
            log.info("========== 匹配完成 ==========");
        }
        return msg.toString();
    }

@Override
	public List<AmazonOrdersDetailVo> selectOrderDetail(Map<String, Object> paramMap) {
		boolean isdeep=paramMap.get("isdeep")==null?false:paramMap.get("isdeep").toString().equals("true");
		paramMap.put("isarchive", "false");
		List<AmazonOrdersDetailVo> list = ordersReportMapper.selectOrderDetail(paramMap);
		if(list==null||list.isEmpty()) {
			 paramMap.put("isarchive", "false");
			 list = ordersReportMapper.selectOrderItemDetail(paramMap);
		}
		if(list==null||list.isEmpty()) {
			 paramMap.put("isarchive", "true");
			 list = ordersReportMapper.selectOrderItemDetail(paramMap);
		}
		if(list==null||list.isEmpty()) {
			 paramMap.put("isarchive", "true");
			 list = ordersReportMapper.selectOrderDetail(paramMap);
		}
		if (list != null && list.size() > 0) {
			String amazonAuthId = list.get(0).getAmazonAuthId();
			String marketplaceId = list.get(0).getMarketplaceId();
			AmazonAuthority amazonAuthority = amazonAuthorityService.getById(amazonAuthId);
			Marketplace marketplace = marketplaceService.getById(marketplaceId);
			amazonAuthority.setMarketPlace(marketplace);
			String orderid = paramMap.get("orderid").toString();
			String itemstatus = list.get(0).getItemstatus();
			boolean nonaddress=false;
			 if(paramMap.get("nonaddress")!=null&&paramMap.get("nonaddress").toString().equals("true")) {
				 nonaddress=true;
			 }
			 if(isdeep) {
				 this.amzOrderMainMapper.deleteById(orderid);
				 LambdaQueryWrapper<AmzOrderItem> queryWrapper=new LambdaQueryWrapper<AmzOrderItem>();
				 queryWrapper.eq(AmzOrderItem::getAmazonOrderId, orderid);
				this.amzOrderItemMapper.delete(queryWrapper);
			 }
			 AmzOrderMain orderMain = this.saveOrderDetail(orderid, amazonAuthority, itemstatus,nonaddress);
				if (orderMain != null && orderMain.getOrderItemList() != null) {
					paramMap.put("amazonAuthId", amazonAuthId);
					List<AmazonOrdersDetailVo> list_item = amzOrderItemMapper.selectOrderDetail(paramMap);// 从数据库拿amz_order_item里面的数据
					if (list_item != null && list_item.size() > 0) {
						list = list_item;
					}
		    }
			for (AmazonOrdersDetailVo map : list) {
				String itemtax = map.getItemtax().toString();
				String region = map.getRegion();
				Object totalprice = map.getTotalprice();
				String sn = generateNumber(amazonAuthority.getShopId(),orderid);
				map.setInvoiceNo(sn);
				if (("EU".equals(region)||"UK".equals(region))&& Float.valueOf(itemtax) == 0.0 && totalprice!=null) {
					if(map.getVatRate()!=null) {
						String vat_rate = map.getVatRate().toString();
						float rate = Float.valueOf(vat_rate) / 100;
						float number = (Float.valueOf(totalprice.toString()) * rate) / (1 + rate);
						map.setItemtax(new BigDecimal(GeneralUtil.formatterNum(number)).setScale(2, RoundingMode.HALF_UP));
					}

				}
			}
			if (orderMain != null) {
				list.get(0).setOrderprice(orderMain.getOrderTotal());
				list.get(0).setOrderstatus(orderMain.getOrderStatus());
				if (orderMain.getBuyerAdress() != null) {
					list.get(0).setAddressName(orderMain.getBuyerAdress().getName());
					String adress = orderMain.getBuyerAdress().getAddressLine1();
					if (adress == null) {
						adress = orderMain.getBuyerAdress().getAddressLine2();
					}
					if (adress == null) {
						adress = orderMain.getBuyerAdress().getAddressLine3();
					}
					list.get(0).setBuyername(orderMain.getBuyerAdress().getName());
					list.get(0).setBuyeremail(orderMain.getBuyerAdress().getName());
					list.get(0).setAddressLine(adress);
					list.get(0).setItemstatus(orderMain.getOrderStatus());
					list.get(0).setAddressState(orderMain.getBuyerAdress().getStateOrRegion());
					list.get(0).setAddressCity(orderMain.getBuyerAdress().getCity());
					list.get(0).setAddressCountry(orderMain.getBuyerAdress().getCountryCode());
					list.get(0).setAddressPostal(orderMain.getBuyerAdress().getPostalCode());
					list.get(0).setHasAddress("has");
				}else {
					list.get(0).setHasAddress("nohas");
				}
				list.get(0).setOrderMain(orderMain);
				boolean nonfin=false;
				 if(paramMap.get("nonfin")!=null&&paramMap.get("nonfin").toString().equals("true")) {
					 nonfin=true;
				 }
				if(nonfin==false) {
					List<OrdersFinancial> financialList = ordersFinancialService.getOrdersFinancialList(amazonAuthority,orderid);
					if(financialList!=null) {
						BigDecimal financialfee=new BigDecimal("0");
						for(int i=0;i<financialList.size();i++) {
							OrdersFinancial fin = financialList.get(i);
							String ename = fin.getFtype();
							QueryWrapper<AmzAmountDescription> queryWrapper=new QueryWrapper<AmzAmountDescription>();
							queryWrapper.eq("ename", ename);
							AmzAmountDescription description = amzAmountDescriptionMapper.selectOne(queryWrapper);
							if(description!=null) {
								fin.setMarketplaceId(description.getCname());
							}else {
								fin.setMarketplaceId(ename);
							}
							financialfee=financialfee.add(fin.getAmount());
						}
						list.get(0).setFinancialList(financialList);
						list.get(0).setFinancialfee(financialfee);
					}
				}
				for (AmazonOrdersDetailVo map : list){
					String sku = map.getSku();
					String amzorderid = orderMain.getAmazonOrderId();
					OrdersReport ordersReports = ordersReportMapper.selectBySkuOrder(sku,amzorderid);
					if(ordersReports!=null ){
						ordersReports.setOrderStatus(orderMain.getOrderStatus());
						ordersReports.setLastUpdatedDate(orderMain.getLastUpdatedDate());
						QueryWrapper<OrdersReport> query=new QueryWrapper<OrdersReport>();
						query.eq("amazonAuthId", ordersReports.getAmazonauthid());
						query.eq("amazon_order_id", ordersReports.getAmazonOrderId());
						query.eq("sku", ordersReports.getSku());
						query.eq("sales_channel", ordersReports.getSalesChannel());
						ordersReportMapper.update(ordersReports,query);

					}
				}

			}
			return list;
		} else {
			return null;
		}

	}

@Override
    public boolean reconcileSupplier(String groupid, String supplierId, String operator,
                                      Map<String, Object> reconcileData) {
        if (groupid == null || supplierId == null) {
            log.warn("对账参数不完整：groupid={}, supplierId={}", groupid, supplierId);
            return false;
        }

        log.info("开始对账：groupid={}, supplierId={}", groupid, supplierId);

        // 从ERP获取供应商列表，找到对应供应商的名称和账户名称
        try {
            Result<?> supplierResult = remoteERPService.getSupplierList();
            if (!Result.isSuccess(supplierResult) || !(supplierResult.getData() instanceof List)) {
                log.warn("获取ERP供应商列表失败");
                return false;
            }
            List<Map<String, Object>> supplierList = (List<Map<String, Object>>) supplierResult.getData();
            log.info("获取ERP供应商数量：{}", supplierList.size());

            // 找到目标供应商，收集其名称和账户名称
            List<String> sellerNames = new ArrayList<>();
            String supplierName = null;
            String companyName = null;
            for (Map<String, Object> supplier : supplierList) {
                Object idObj = supplier.get("id");
                if (idObj != null && idObj.toString().equals(supplierId)) {
                    Object nameObj = supplier.get("name");
                    if (nameObj != null) {
                        supplierName = nameObj.toString().trim();
                        sellerNames.add(supplierName);
                    }
                    // 获取公司名
                    Object companyObj = supplier.get("company");
                    if (companyObj == null) {
                        companyObj = supplier.get("companyName");
                    }
                    if (companyObj != null) {
                        companyName = companyObj.toString().trim();
                    }
                    Object accountNamesObj = supplier.get("accountNames");
                    if (accountNamesObj != null && !accountNamesObj.toString().isEmpty()) {
                        String[] accountNames = accountNamesObj.toString().split(",");
                        for (String accountName : accountNames) {
                            String trimmedName = accountName.trim();
                            if (!trimmedName.isEmpty()) {
                                sellerNames.add(trimmedName);
                            }
                        }
                    }
                    break;
                }
            }

            log.info("找到供应商的销方名称：{}，公司名：{}", sellerNames, companyName);
            if (sellerNames.isEmpty()) {
                log.warn("未找到供应商的销方名称，supplierId={}", supplierId);
                return false;
            }

            // 更新发票对账状态
            int rows = finSupplierLedgerMapper.updateReconcileStatusByNames(groupid, sellerNames, operator);
            log.info("对账更新行数：{}", rows);

            // 保存对账记录到数据库
            if (reconcileData != null) {
                String reconcileMonth = reconcileData.get("reconcileMonth") != null ? reconcileData.get("reconcileMonth").toString() : null;

                // 先查询是否已存在该月份的对账记录
                FinSupplierReconcileRecord existingRecord = null;
                if (reconcileMonth != null && !reconcileMonth.isEmpty()) {
                    existingRecord = finSupplierLedgerMapper.selectReconcileRecord(groupid, supplierId, reconcileMonth);
                }

                FinSupplierReconcileRecord record = existingRecord != null ? existingRecord : new FinSupplierReconcileRecord();
                record.setGroupid(groupid);
                record.setSupplierId(supplierId);
                record.setSupplierName(supplierName);
                // 优先使用前端传入的公司名，如果没有则使用ERP中的公司名
                String finalCompanyName = reconcileData.get("companyName") != null && !reconcileData.get("companyName").toString().isEmpty() 
                    ? reconcileData.get("companyName").toString() : companyName;
                record.setCompanyName(finalCompanyName);
                record.setReconcileMonth(reconcileMonth);
                record.setOrderCount(reconcileData.get("orderCount") != null ? Integer.parseInt(reconcileData.get("orderCount").toString()) : 0);
                record.setTotalOrderAmount(reconcileData.get("totalOrderAmount") != null ? new BigDecimal(reconcileData.get("totalOrderAmount").toString()) : BigDecimal.ZERO);
                record.setTotalReceived(reconcileData.get("totalReceived") != null ? Integer.parseInt(reconcileData.get("totalReceived").toString()) : 0);
                record.setTotalPaidAmount(reconcileData.get("totalPaidAmount") != null ? new BigDecimal(reconcileData.get("totalPaidAmount").toString()) : BigDecimal.ZERO);
                record.setTotalUnpaidAmount(reconcileData.get("totalUnpaidAmount") != null ? new BigDecimal(reconcileData.get("totalUnpaidAmount").toString()) : BigDecimal.ZERO);
                record.setTotalInvoicedAmount(reconcileData.get("totalInvoicedAmount") != null ? new BigDecimal(reconcileData.get("totalInvoicedAmount").toString()) : BigDecimal.ZERO);
                record.setTotalUninvoicedAmount(reconcileData.get("totalUninvoicedAmount") != null ? new BigDecimal(reconcileData.get("totalUninvoicedAmount").toString()) : BigDecimal.ZERO);
                record.setReconcileBy(operator);
                record.setReconcileTime(new Date());

                if (existingRecord != null) {
                    // 更新已有记录（支持反复对账覆盖）
                    log.info("更新对账记录，recordId={}, 新时间={}", record.getId(), record.getReconcileTime());
                    int updateRows = finSupplierLedgerMapper.updateReconcileRecord(record);
                    log.info("对账记录更新影响行数：{}", updateRows);
                    if (updateRows <= 0) {
                        log.error("对账记录更新失败，recordId={}，影响行数为0", record.getId());
                        return false;
                    }
                } else {
                    // 插入新记录
                    int insertRows = finSupplierLedgerMapper.insertReconcileRecord(record);
                    log.info("对账记录插入结果，recordId={}, 影响行数={}", record.getId(), insertRows);
                    if (insertRows <= 0) {
                        log.error("对账记录插入失败，supplierId={}, reconcileMonth={}", supplierId, reconcileMonth);
                        return false;
                    }
                }
                return true;
            }

            return rows > 0;
        } catch (Exception e) {
            log.error("对账操作失败", e);
            return false;
        }
    }

public Material saveMaterial(DimensionsInfo itemdim,DimensionsInfo pkgdim,DimensionsInfo boxdim,MaterialInfoVO vo,MultipartFile file,MultipartFile pkgfile,UserInfo user) {
		MaterialVO materialvo=vo.getMaterial();
		QueryWrapper<Material> queryWrapper=new QueryWrapper<Material>();
		queryWrapper.eq("shopid", user.getCompanyid());
		queryWrapper.eq("sku", vo.getMaterial().getSku());
		String oldowner=null;
		boolean isupdate=true;
		String oldpicture=null;
		String oldpkgpicture=null;
		Material  material= this.baseMapper.selectOne(queryWrapper);
