			  material = new Material();
			  String uuid = warehouseService.getUUID();
			  if(StrUtil.isBlank(uuid)) {
				  throw new ERPBizException("生成物料ID失败，请重试！");
			  }
			  material.setId(uuid);
			  isupdate=false;
		}else {
			if(material.isDelete()) {
				throw new ERPBizException("产品SKU："+ material.getSku() +"已经归档，请从归档状态还原后使用!");
			}else  if(!material.getId().equals(vo.getMaterial().getId())) {
				throw new ERPBizException("该SKU已经存在！");
			}else {
				if(vo.getMaterial().getIssfg()!=null && (material.getIssfg()==null || !material.getIssfg().equals(vo.getMaterial().getIssfg()) )) {
					QueryWrapper<PurchasePlanItem> checkquery=new QueryWrapper<PurchasePlanItem>();
					checkquery.eq("materialid", materialvo.getId());
					checkquery.eq("shopid", user.getCompanyid());
					List<PurchasePlanItem> purchaseList = purchasePlanItemService.list(checkquery);
					if (purchaseList != null && purchaseList.size() > 0) {
						throw new ERPBizException("已加入补货计划，请移除后再修改产品组装类别！");
					}
			     }

			}
			oldowner=material.getOwner();
			oldpicture=material.getImage();
			oldpkgpicture=material.getPkgimage();
		}
       String pictureid=null;
		if("ok".equals(vo.getIscopy()) && file==null) {
			if(vo.getMaterial().getImageid()!=null) {
				Picture oldpic = pictureService.getById(vo.getMaterial().getImageid());
				if(oldpic!=null) {
					Picture pic=new Picture();
					pic.setHeight(oldpic.getHeight());
					pic.setHeightUnits(oldpic.getHeightUnits());
					pic.setLocation(oldpic.getLocation());
					pic.setUrl(oldpic.getUrl());
					pic.setWidth(oldpic.getWidth());
					pic.setWidthUnits(oldpic.getWidthUnits());
					boolean isok = pictureService.save(pic);
					if(isok==true) {
						material.setImage(pic.getId());
					}
				}
			}
		}
		if(file!=null) {
			//改变了图片
			try {
				pictureid=this.uploadMaterialImg(user, material.getId(), file.getInputStream(), file.getOriginalFilename(),oldpicture);
				material.setImage(pictureid);
			} catch (IOException e) {
				e.printStackTrace();
			}
		}
		if(pkgfile!=null) {
			try {
				pictureid=this.uploadMaterialImg(user, material.getId(), pkgfile.getInputStream(), pkgfile.getOriginalFilename(),oldpkgpicture);
				material.setPkgimage(pictureid);
			} catch (IOException e) {
				e.printStackTrace();
			}
		}else{
			if(StrUtil.isEmpty(vo.getMaterial().getLocation())&&material.getPkgimage()!=null){
			    pictureService.removePicture(material.getPkgimage());
				material.setPkgimage(null);
			}
		}
		material.setShopid(user.getCompanyid());
		material.setOpttime(new Date());
		material.setOperator(user.getId());
		if(isupdate==false) {
			material.setCreator(material.getOperator());
			material.setCreatedate(new Date());
		}
		material.setPrice(materialvo.getPrice());
		material.setOtherCost(materialvo.getOtherCost());
		material.setBoxnum(materialvo.getBoxnum());
		material.setAddfee(materialvo.getAddfee());
		material.setVatrate(materialvo.getVatrate());
		material.setDrawbackRate(materialvo.getDrawbackRate());
		if(GeneralUtil.isNotEmpty(materialvo.getCategoryid())) {
			material.setCategoryid(materialvo.getCategoryid());
		}
		material.setOwner(materialvo.getOwner());
		material.setSku(materialvo.getSku());
		material.setUpc(materialvo.getUpc());
		material.setName(materialvo.getName());
		material.setSmlAndLight(false);
		material.setBrandid(materialvo.getBrandid());
		if(StrUtil.isNotBlank(materialvo.getGroupid())){
			material.setGroupid(materialvo.getGroupid());
		}else{
			material.setGroupid(null);
		}
		material.setSpecification(materialvo.getSpecification());
		material.setIsAssPrice(materialvo.getIsAssPrice());
		if(material.getIssfg()==null) {
			material.setIssfg("0");
		}
		material.setRemark(materialvo.getRemark());
		material.setColor(null);
		material.setMtype(materialvo.getMtype()==null?0:materialvo.getMtype());
		material.setDeliveryCycle(materialvo.getDeliveryCycle());
		material.setEffectivedate(materialvo.getEffectivedate());
		if(itemdim!=null) {
			material.setItemdimensions(itemdim.getId());
		}else {
			material.setItemdimensions(null);
		}
		if(boxdim!=null) {
			material.setBoxdimensions(boxdim.getId());
		}else {
			material.setBoxdimensions(null);
		}
		if(pkgdim!=null) {
			material.setPkgdimensions(pkgdim.getId());
		}else {
			material.setPkgdimensions(null);
		}
		//组装周期
		if (materialvo.getAssemblyTime() != null) {
			int assemblyTime = materialvo.getAssemblyTime();
			material.setAssemblyTime(assemblyTime);
		} else {
			int assemblyTime = 0;
			material.setAssemblyTime(assemblyTime);
		}
		 try {
			//同步修改产品的负责人
			 if(material.getOwner()!=null) {
				 amazonClientOneFeign.updateProductOwner(material.getSku(),material.getOwner(),oldowner);
			 }
		 }catch(Exception e) {
			 e.printStackTrace();
		 }
		if(isupdate){
				  this.baseMapper.updateById(material);
				  ERPMaterialHistory his=new ERPMaterialHistory();
				  BeanUtil.copyProperties(material, his);
				  erpMaterialHistoryMapper.insert(his);
				  return material;
		}else {
			     this.baseMapper.insert(material);
				  ERPMaterialHistory his=new ERPMaterialHistory();
				  BeanUtil.copyProperties(material, his);
				  erpMaterialHistoryMapper.insert(his);
				  return material;
		}

	}

public CostDetail initCostDetail(String country, ProfitConfig profitCfgAll, InputDimensions inputDimension,
			String isMedia, String type, int typeId, BigDecimal cost, BigDecimal shipment, String currency,
			String category, String shipmentType, BigDecimal declaredValue, String declaredValueCur,
			BigDecimal taxrate, BigDecimal gstrate, BigDecimal sellingGSTRate,BigDecimal referralrate, boolean isSmlAndLight,Boolean sipp) 
					throws BizException {
		// 对用户输入的长宽高重新排序
		initDimensionSort(inputDimension);

		CostDetail costDetail = new CostDetail();
		costDetail.setCountry(country);
		////为了亚马逊选品库计算利润返回货币符号
		String fcurrency = GeneralUtil.formatCurrency(getCurrencyUnit(country));
		costDetail.setCurrency(fcurrency);//符号简写，如：$

		ProfitConfigCountry profitConfigX = profitCfgAll.getProfitConfigCountry(country);//得到各个国家的利润方案
		if(profitConfigX==null){
			return null;
		}
		IProfitService profitServiceX = null;
		try {
			profitServiceX = factoryProfitServiceByCountry(country);
		} catch (Exception e) {
			e.printStackTrace();
		}
		if (profitServiceX==null) {
			return null;
		}
		////采购成本
		String to = getCurrencyUnit(country);
		cost = this.exchangeRateHandlerService.changeCurrencyByLocal(currency, to, cost);//单位转换
		costDetail.setPurchase(cost);
		//// 本地运费
		shipment = calculateShipment(profitCfgAll, profitConfigX, currency, to, inputDimension,shipment);
		if (shipment == null) {
			return null;
		}
		costDetail.setShipment(shipment);

		String channel = profitCfgAll.getSalesChannel();
		boolean isStandard = true;
		if (channel.contains("fba")) {// 如果利润计算方案是FBA，印度目前只支持FBA
			if (isSmlAndLight && Arrays.asList(smlAndLightCountry).contains(country)) {
				String productTierId = profitServiceX.determineSmlProductTier(country, inputDimension,isMedia);// 公用方法
				if (productTierId == null) {
					return null;
				}
				if(country.equals("UK")&&profitConfigX.getFenpeiType().equals("EFN")) {
					return null;
				}
				costDetail.setProductTierId(productTierId);
				ProductTier productTier = productTierService.selectByPKey(productTierId);
				String productTierName = productTier.getName();
				costDetail.setProductTier(productTierName);
				BigDecimal outboundWeight = profitServiceX.getSLOutboundWeight(country, productTier, inputDimension);
				costDetail.setOutboundWeight(outboundWeight);

				BigDecimal FBA = profitServiceX.calculateSmlFBA(country, productTierId, outboundWeight,profitConfigX,type);

				BigDecimal sippfee =new BigDecimal("0");
				if(sipp!=null&&sipp==false) {
					sippfee=profitServiceX.calculateFBASIPP(country, productTierId, inputDimension, isMedia, type,outboundWeight, profitConfigX,sipp);
				}
				FBA=FBA.subtract(sippfee);
				costDetail.setFBA(FBA);
				costDetail.setSipp(sippfee);
			} else {
				String productTierId = profitServiceX.determineProductTier(country, inputDimension, isMedia);
				// 当该国家找不到产品层级时，尝试使用仓库站点国家的数据作为回退
				if (productTierId == null) {
					String warehousesite = profitConfigX.getWarehousesite();
					if (StrUtil.isNotBlank(warehousesite) && !warehousesite.equalsIgnoreCase(country)) {
						productTierId = profitServiceX.determineProductTier(warehousesite.toUpperCase(), inputDimension, isMedia);
					}
				}
				if (productTierId == null) {
					return null;
				}
				costDetail.setProductTierId(productTierId);
				ProductTier productTier = productTierService.selectByPKey(productTierId);
				String productTierName = productTier.getName();
				isStandard = productTier.getIsstandard();
				BigDecimal outboundWeight = profitServiceX.determineOutboundWeight(country, productTier, inputDimension,isMedia);
				costDetail.setProductTier(productTierName);
				costDetail.setOutboundWeight(outboundWeight);

				BigDecimal manualProcessingFee = profitConfigX.getManualProcessing();// 只有美国有这笔费用
				costDetail.setManualProcessingFee(manualProcessingFee);

				BigDecimal inPlaceFee = profitServiceX.calculateInPlaceFee(country, productTier, inputDimension,
						profitConfigX.getInvplacefee());// 加复选框，可选择不加上这个成本；如果选中要计算，则按产品重量对应计上成本,只有US和JP有这个费用选项
				costDetail.setInPlaceFee(inPlaceFee);

				// boolean prepService = profitConfigX.getPrepservice();
				// if (prepService) {//日本没有prep Service fee
				// BigDecimal prepServiceFee =
				// getPrepServiceFee(isStandard,country,category);
				// costDetail.setPrepServiceFee(prepServiceFee);
				// }

				BigDecimal FBA = profitServiceX.calculateFBA(country, productTierId, inputDimension, isMedia, type,outboundWeight, profitConfigX, shipmentType);
				BigDecimal sippfee =profitServiceX.calculateFBASIPP(country, productTierId, inputDimension, isMedia, type,outboundWeight, profitConfigX,sipp);
				FBA=FBA.subtract(sippfee);
				costDetail.setFBA(FBA);
				costDetail.setSipp(sippfee);
			}

			boolean labelService = profitConfigX.getLabelService();
			if (labelService) {
				BigDecimal labelServiceFee = getLabelServiceFee(isStandard, country, isSmlAndLight);
				costDetail.setLabelServiceFee(labelServiceFee);
			}
			BigDecimal storageFee = profitServiceX.calculateStorageFee(country, profitConfigX, inputDimension,
					isStandard);
			costDetail.setStorageFee(storageFee);

			// 亚马逊收费GST 税率
			BigDecimal fbaGSTTax = profitConfigX.getFbaTaxes().divide(new BigDecimal("100"), 4,
					RoundingMode.HALF_UP);
			costDetail.setFbaTax(fbaGSTTax);
			if ("CA".equals(country)) {
				BigDecimal fbaTaxFee = costDetail.getFBA().multiply(fbaGSTTax).setScale(4, RoundingMode.HALF_UP);
				costDetail.setFbaTaxFee(fbaTaxFee);
			}
			//////////////////////////// 由于亚马逊销售佣金, Fixed Closing
			//////////////////////////// Fee与售价有关，先忽略不计入成本,得到售价之后再计入///////////////
			if ("IN".equals(country)) {
				// 亚马逊收费GST税率默认18%, 应用于亚马逊销售佣金, Fixed Closing Fee, FBA fee等
				BigDecimal fbaTaxFee = costDetail.getFBA().multiply(fbaGSTTax).setScale(4, RoundingMode.HALF_UP);
				costDetail.setFbaTaxFee(fbaTaxFee);
			}

		} else if (channel.contains("byself")) {// 自发货方式
			if (isSmlAndLight) {
				return null;
			}
			if ("IN".equals(country)) {// 印度只支持FBA
				return null;
			}
			BigDecimal VCFee = profitServiceX.calculateVCFee(country, isMedia, typeId);
			costDetail.setVCFee(VCFee);
		}

		String sellerPlan = profitCfgAll.getSellerplan();//分为：个人卖家，专业卖家
		BigDecimal perItemFee = new BigDecimal("0");
		if (sellerPlan.equals("person")) {//个人卖家
			perItemFee = getIndividualFee(country);
			costDetail.setPerItemFee(perItemFee);
		}
		//对于比率类费用，除以100转换成小数，四舍五入
		if (referralrate!=null) {
			referralrate = referralrate.divide(new BigDecimal("100"),4,RoundingMode.HALF_UP);
		}

		//Currency Transport fee 計算方式：销售额 减去 亚马逊直接的收费之后(FBA费, 拥金, storage费等) , 余额部份再 X 汇率损耗率
		BigDecimal lostrate = profitConfigX.getLostrate().divide(new BigDecimal("100"),4,RoundingMode.HALF_UP);//Currency Transport fee
		BigDecimal sellerrate = profitConfigX.getSellerrate().divide(new BigDecimal("100"),4,RoundingMode.HALF_UP);//Marketing
		BigDecimal costrate = profitConfigX.getCostrate().divide(new BigDecimal("100"),4,RoundingMode.HALF_UP);//其它每单销售固定成本比率
//		BigDecimal promotion = profitConfigX.getPromotion().divide(new BigDecimal("100"),4,RoundingMode.HALF_UP);//all store promotion
		BigDecimal rateFee = sellerrate.add(costrate);//所有售价*rateFee的费用
		BigDecimal others = profitConfigX.getOtherfee();//OTHERS
		//VAT增值税费率
		BigDecimal vatRate=profitConfigX.getVatRate().divide(new BigDecimal("100"),4,RoundingMode.HALF_UP);
		if (!"IN".equals(country) || taxrate == null || gstrate == null || sellingGSTRate == null) {
			taxrate = profitConfigX.getTaxrate();
			gstrate = profitConfigX.getGstrate();
			sellingGSTRate = profitConfigX.getSellingGSTRate();
		}
		//进口关税税率
		taxrate = taxrate.divide(new BigDecimal("100"),4,RoundingMode.HALF_UP);
		//进口GST税率
		gstrate = gstrate.divide(new BigDecimal("100"),4,RoundingMode.HALF_UP);
		//销售GST税率
		sellingGSTRate=sellingGSTRate.divide(new BigDecimal("100"),4,RoundingMode.HALF_UP);
		//企业所得税率
		BigDecimal corporateInRate=profitConfigX.getCorporateInRate().divide(new BigDecimal("100"),4,RoundingMode.HALF_UP);

		costDetail.setCurrencyTransportRate(lostrate);
		costDetail.setMarketingRate(sellerrate);
		costDetail.setOtherRate(costrate);
		costDetail.setRateFee(rateFee);
//		costDetail.setPromotionRate(promotion);
		costDetail.setOthers(others);
		costDetail.setVatRate(vatRate);
		costDetail.setTaxRate(taxrate);
		costDetail.setGstrate(gstrate);
		costDetail.setSelling_GSTRate(sellingGSTRate);
		costDetail.setCorporateInRate(corporateInRate);

		if ("IN".equals(country) && profitConfigX.isHasDeclaredValue()) {
			if (declaredValue == null) {// 当商品利润分析用任务计算时，declaredValue==null
				return null;
			}
			declaredValue = this.exchangeRateHandlerService.changeCurrencyByLocal(declaredValueCur, to, declaredValue);// 单位转换
		} else {
			declaredValue = cost.add(shipment);// 申报价值 = 采购价+运费
		}
		//进口关税=申报价值 * 关税税率
		BigDecimal tax = declaredValue.multiply(taxrate).setScale(4, RoundingMode.HALF_UP);
		costDetail.setTax(tax);
		//进口GST税费=(申报价值+关税) * GST税率
		BigDecimal import_gst=(new BigDecimal("1").add(taxrate)).multiply(declaredValue)
				.multiply(gstrate).setScale(4, RoundingMode.HALF_UP);
		costDetail.setImport_GST(import_gst);
		List<Map<String, String>> resultList = calculateSellingPrice(costDetail, typeId, country, referralrate);// 按固定利率估算售价和利润
		costDetail.setResultList(resultList);
		return costDetail;
	}

@PostMapping(value = "/uploadPaymentFile",consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
		public Result<String> uploadPaymentFileAction(@RequestParam("file")MultipartFile file)  {
		       UserInfo user=UserInfoContext.get();
		       List<FinanceProject> projectlist = iFinanceProjectService.findProject(user.getCompanyid());
		       List<PurchaseFormPaymentMethod> paymethlist = iFaccountService.findPurchasePayMethod(user.getCompanyid());
		       Map<String,FinanceProject> projectMap=new HashMap<String,FinanceProject>();
		       Map<String,PurchaseFormPaymentMethod> paymethMap=new HashMap<String,PurchaseFormPaymentMethod>();
		       for(FinanceProject item:projectlist) {
		    	   projectMap.put(item.getName(), item);
		       }
		       for(PurchaseFormPaymentMethod item:paymethlist) {
		    	   paymethMap.put(item.getName(), item);
		       }
				if (file != null) {
					try {
						InputStream inputStream = file.getInputStream();
						Workbook workbook = WorkbookFactory.create(inputStream);
						Map<String,PurchaseFormEntry> entryMap=new HashMap<String,PurchaseFormEntry>();
						Sheet sheet = workbook.getSheetAt(0);
						String message="";
						for (int i = 1; i <= sheet.getLastRowNum(); i++) {
							Row info=sheet.getRow(i);
							if(info==null || info.getCell(0)==null) {
								continue;
							}
							Cell numbercell = info.getCell(0);
							String number = numbercell.getStringCellValue();
							if(StrUtil.isBlank(number)){
								throw new BizException("第"+(i+1)+"行，采购单号不能为空");
							}
							number=number.replaceAll(" ", "");
							number=number.trim();
							Cell skucell=info.getCell(1);
							String sku=skucell.getStringCellValue();
							if(StrUtil.isBlank(sku)){
								throw new BizException("第"+(i+1)+"行，采购单号"+number+"对应SKU不能为空");
							}
							sku=sku.replaceAll(" ", "");
							sku=sku.trim();

							Cell feetypecell=info.getCell(2);
							String feetype=feetypecell!=null?feetypecell.getStringCellValue():null;
							if(StrUtil.isBlank(feetype)){
								throw new BizException("第"+(i+1)+"行，采购单号"+number+"对应"+sku+"费用类型不能为空");
							}
							feetype=feetype.replaceAll(" ", "");
							feetype=feetype.trim();
							Cell paytypecell=info.getCell(3);
							String paytype=paytypecell!=null?paytypecell.getStringCellValue():null;
							if(StrUtil.isBlank(paytype)){
								throw new BizException("第"+(i+1)+"行，采购单号"+number+"对应"+sku+"支付方式不能为空");
							}
							paytype=paytype.replaceAll(" ", "");
							paytype=paytype.trim();
							Cell payacctcell=info.getCell(4);
							String payacct=payacctcell!=null?payacctcell.getStringCellValue():null;
							payacct=payacct.replaceAll(" ", "");
							payacct=payacct.trim();

							Cell amountcell=info.getCell(5);
							Double amount =amountcell!=null? amountcell.getNumericCellValue():null;
							if(amount==null){
								throw new BizException("第"+(i+1)+"行，采购单号"+number+"对应"+sku+"支付费用不能为空");
							}
							Cell remarkcell=info.getCell(6);
							String remark=null;
							if(remarkcell!=null) {
								remark=remarkcell.getStringCellValue();
							}
							String key=user.getCompanyid()+number+sku;
							PurchaseFormEntry entry = entryMap.get(key);
							if(entry==null) {
								  entry = purchaseFormEntryService.getByNumberSku(user.getCompanyid(),number,sku);
							}
							if(entry!=null && entry.getPaystatus()!=null && entry.getPaystatus()==1) {
								throw new BizException("第"+(i+1)+"行，采购单号"+number+"对应"+sku+"订单已付款结清，不支持再次付款！");
							}
							FinanceProject feetypeEntity = projectMap.get(feetype);
							PurchaseFormPaymentMethod paytypeEntity = paymethMap.get(paytype);
							if(amount!=null&&feetypeEntity!=null&&paytypeEntity!=null&&entry!=null&&amount>0.0000001) {
								PurchaseFormPayment pay =new PurchaseFormPayment();
								List<PurchaseFormPayment> paylist = entry.getPayList();
								if(paylist==null) {
									paylist=new LinkedList<PurchaseFormPayment>();
								}
								pay.setProjectid(feetypeEntity.getId());
								pay.setProjectname(feetypeEntity.getName());
								pay.setPaymentMethod(paytypeEntity.getId());
								pay.setMethodname(paytypeEntity.getName());
								FinAccount fin = iFaccountService.readFinAccount(user.getCompanyid(), pay.getPaymentMethod(),payacct);
								pay.setAcct(fin.getId());
								pay.setAuditstatus(1);
								pay.setCreatedate(new Date());
								pay.setOpttime(new Date());
								pay.setOperator(user.getId());
								pay.setFormentryid(entry.getId());
								pay.setPayprice(new BigDecimal(amount));
								pay.setRemark((remark==null?"":remark)+" 批量导入");
								paylist.add(pay);
								entry.setPayList(paylist);
								entryMap.put(key,entry);
							}else {
								message=message+"订单编码:"+number+",SKU:"+sku+",费用类型:"+feetype+",付款方式:"+paytype+"无法匹配，或金额为空";
							}

						}
						if(!StrUtil.isBlankOrUndefined(message)) {
							throw new BizException(message);
						}
						for(Entry<String, PurchaseFormEntry> item:entryMap.entrySet()) {
							iPurchaseFormPaymentService.updatePayment(item.getValue().getPayList(),item.getValue(),null, user);
				        }

						workbook.close();
						return Result.success();
					} catch (IOException e) {
						e.printStackTrace();
						return Result.failed();
					} catch (EncryptedDocumentException e) {
						e.printStackTrace();
					}
				}
			return Result.success("ok");
		}
